export type BikeOverview={years:number[];generation:string;summary:string;points:{aspect:string;verdict:string;statement:string;years:number[];support:number;strength:string}[];common_fixes:{problem:string;fix:string;result:string;support:number}[];disagreements:{topic:string;sides:string[]}[]};
export const bikeOverviews:Record<string,BikeOverview[]>={"Honda|CRF250R":[{"years":[2020,2021],"generation":"2020-2021 (twin-muffler engine, 2020 frame and suspension update)","summary":"A high-revving 250 whose strength is top-end and over-rev; most US testers still found the bottom end soft and needing the clutch, despite Honda's 2020 low-end changes. The Showa suspension was rated plush and easy to set up, though faster or heavier riders found the fork divey and the shock empty on G-outs. Testers reported a twitchy front or head shake in rough ground (one cause was a steering-head nut left loose from the factory) and an engine that runs hot when idling. Aftermarket full exhausts and a plug-in ECU were the usual low-end fixes.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Bottom end feels soft and lazy; power comes in late and the clutch is needed to wake it up out of corners.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Pulls hard at high rpm and over-revs further than most rival 250Fs; it rewards being kept on the boil.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Showa suspension is plush and easy to set up for an average rider.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Front can feel twitchy, knife into corners or shake at speed in rough ground, especially for lighter riders; one cause found was a loose steering-head nut from the factory.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"For fast or 170 lb-plus riders the fork dives under hard braking and the shock runs out of support at the end of the stroke on G-outs.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Runs hot when idling or in long high-rpm motos and can push coolant out of the overflow.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Aggressive map chosen for more torque out of corners; standard map also usable because it pulls longer in second and third.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Rear fender can break if used to lift the bike, engine-cover paint scratches early and the twin mufflers are costly to replace.","years":[2020,2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom end out of corners","fix":"Aftermarket full exhaust system (slip-ons or silencer inserts lose most of the benefit)","result":"Better bottom and low-mid pull and quicker second/third gear recovery, so a higher gear can be held; no top-end loss","support":1},{"problem":"Weak bottom end","fix":"Plug-in aftermarket ECU","result":"More low-end grunt and longer-pulling gears than any exhaust tested","support":1},{"problem":"Third gear hard to use","fix":"One tooth larger rear sprocket (13/49)","result":"Third gear became usable in corners","support":1},{"problem":"Fork dive and head shake","fix":"Stiffer fork compression and forks raised from 5 mm to about 3 mm in the clamps (back toward flush or 5 mm if it shakes or stands up)","result":"Calmer front on braking and corner entry","support":2},{"problem":"Shock empty on G-outs","fix":"High-speed compression about 1/8 turn in and sag around 100-103 mm","result":"Rear held up better on G-outs; 105 mm sag added stability but slowed turning","support":2},{"problem":"Twitchy front, knifing","fix":"Snug the steering-head nut","result":"Front settled","support":1}],"disagreements":[{"topic":"Bottom-end strength","sides":["Most US tests found the low end soft and lethargic.","One Australian test of the 2020 found it pulled early with a strong midrange."]}]},{"years":[2022,2023,2024],"generation":"2022-2024 (single exhaust, low-mid engine, CRF450R-style frame)","summary":"The 2022 redesign swapped the old top-end character for much stronger bottom and midrange pull, but the engine falls off early on top and trails the class on peak power. Testers rate it among the best-turning 250s, yet most found the chassis rigid and touchy, with a twitchy front and head shake that needs setup work. The stock Showa fork was widely called too stiff and harsh while the shock felt soft, and both ends react to single-click changes. Common fixes are fork oil and valving changes, longer-offset clamps, a bigger rear tire and a tooth more on the rear sprocket.","points":[{"aspect":"stability","verdict":"weakness","statement":"Frame feels rigid and touchy: twitchy front, mid-corner oversteer and head shake for lighter riders, with fore-aft balance hard to find.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Much stronger bottom-to-mid pull than the 2020-2021 bike; it exits corners with little clutch.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Power falls off after the midrange and lacks over-rev, so a lower gear is often needed in corners.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Measured peak power sits at or near the bottom of the 250F class.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock fork is firm and harsh late in the stroke for riders under about 170 lb while the shock is softer, leaving the bike unbalanced.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"balance","verdict":"weakness","statement":"Very sensitive to single clicks, especially shock high-speed compression: stiffening it puts weight on the front and makes the fork harsher.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"tires","verdict":"weakness","statement":"Stock 100/90-19 rear tire is too narrow for the engine's low-end and gives up grip at lean.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"strength","statement":"Build quality rated highly; the revised water pump stopped coolant loss and the nine-plate clutch survives abuse, though owners still name the clutch and stock chain as early wear items.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Third gear is short so riders often skip to fourth.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"Rated one of the best-cornering 250Fs and more forgiving leaned over than the 450.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"Measured among the lightest 250Fs after dropping the second muffler.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Seat foam breaks down in about 10-12 hours.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Upside-down air filter gets dirty quickly in dust; check it often.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Harsh, stiff fork","fix":"Lower fork oil level about 5 cc per leg and adjust compression; revalve for lighter riders","result":"Less harshness deep in the stroke","support":2},{"problem":"Soft shock, poor acceleration hold-up","fix":"Slower shock low-speed compression and rebound instead of more high-speed compression","result":"More hold-up and exit traction without loading the front","support":2},{"problem":"Twitchy front and head shake","fix":"Longer-offset clamps (23.5-24 mm vs stock 22 mm), plus correct springs, 105-108 mm sag and forks near flush; some added a steering damper","result":"More stability on fast and rough tracks","support":2},{"problem":"Harsh rising-rate rear","fix":"Aftermarket linkage with a more linear rate","result":"Plush start to the stroke that ramps up later","support":1},{"problem":"Short third gear","fix":"13/51 gearing","result":"Third usable in corners","support":1},{"problem":"Lacks top end","fix":"Aftermarket full exhaust","result":"Kept the low end and added midrange, top and quicker recovery; second gear pulls longer","support":1},{"problem":"Overheats when worked hard","fix":"1.8 kg/cm2 high-pressure radiator cap","result":"Holds coolant in hard use","support":1},{"problem":"Seat foam collapses","fix":"Firmer aftermarket foam","result":"Lasts longer","support":1}],"disagreements":[{"topic":"Stock fork firmness","sides":["Most tests found the fork too stiff and harsh.","One 2022 shootout found it too soft with a light rear and added compression."]},{"topic":"Top-end character","sides":["Several tests found it falls off early with a short top end.","One 2022 shootout found it linear and over-revving well."]},{"topic":"Chassis feel","sides":["Several tests called the frame rigid, harsh and nervous.","One tester found it forgiving leaned over and less rigid than the CRF450R."]},{"topic":"Cooling","sides":["One tester found the 2022 pump and louvers cured coolant loss.","Another recommends a higher-pressure cap because it overheats when worked hard."]}]},{"years":[2025,2026],"generation":"2025-2026 (stiffer new frame, revised airbox, linkage and suspension)","summary":"Testers broadly agree the 2025 frame fixed much of the earlier nervousness: the bike is more planted, precise and stable with less pitching, and still feels light. The engine is strong off the bottom but still trails the Austrian bikes and the Kawasaki on top, so most riders prefer the aggressive map. Suspension is plusher than before but soft for riders over about 175 lb or fast riders, and the stock 100/90 Pirelli rear is widely criticised. Common setup moves are lowering the forks toward flush, adding fork compression and stiffer springs for heavier riders.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong off the bottom; easier to drive out of ruts and hold third gear than earlier bikes.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Aggressive map is the most common pick on the stock bike for its extra hit and pull.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Both ends are soft for riders over about 175 lb or fast riders; the shock squats under acceleration.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Mid-to-top pull and over-rev trail the Austrian 250s and the KX250; peak power measures roughly 3-4 hp down.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"More planted and precise with less pitching and front wiggle on entry; needs less effort to hold a line in braking bumps.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"tires","verdict":"weakness","statement":"Stock Pirelli 100/90-19 rear loses traction; testers want a 110 rear.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Fork is plusher over small bumps with a linear ramp; shock stays planted under power.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"neutral","statement":"Can feel harsh in the forearms and busy under braking until fork height and clamp torque are adjusted.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"Feels very light and easy to scrub and whip.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"strength","statement":"Revised front caliper gives a smoother, more linear feel.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"neutral","statement":"Wider midsection grips well but tall riders' legs can catch the shrouds in deep ruts.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Busy front, instability","fix":"Lower the forks from the stock height toward 2-3 mm or flush and run about 103-108 mm sag","result":"Better cornering and stability","support":2},{"problem":"Fork soft as the track roughens or on hard-pack","fix":"Add 2-4 clicks of fork compression (and a couple of clicks of rebound on hard-pack)","result":"Holds up better in braking bumps; cured instability on hard-pack","support":2},{"problem":"Too soft for heavier riders","fix":"Stiffer springs for riders over about 180 lb; fork revalve for heavier or fast intermediate riders","result":"Better hold-up","support":2},{"problem":"Shock squats on acceleration","fix":"Stiffer shock low-speed compression (avoid stiffening high-speed, which made the front harsh)","result":"More support and corner traction","support":2},{"problem":"Forearm harshness","fix":"Lower triple-clamp pinch-bolt torque (check service manual minimums)","result":"Less harshness and better front tire feel","support":1},{"problem":"Lacks top end","fix":"Aftermarket full exhaust, run with the standard map","result":"Felt about 2 hp stronger with better bottom, mid and over-rev","support":1}],"disagreements":[{"topic":"Preferred map","sides":["Most testers prefer the aggressive map.","Another found the aggressive map runs out early and preferred standard."]},{"topic":"Top-end feel","sides":["Most testers say it lacks top-end punch.","One magazine's dyno runs looked better on top than expected, and a long-term tester said it did not feel slow on track."]},{"topic":"Opening the airbox","sides":["One magazine saw no dyno gain from removing the filter cover and backfire screen.","A long-term test bike felt sharper response after removing the screen and enlarging the airbox hole, done together with an ECU remap."]},{"topic":"Gear spacing","sides":["One magazine liked stock gearing and changed nothing.","Other tests found first and second long and a gap to third that revs out quickly."]},{"topic":"Bottom-end torque in mud","sides":["Most say it is strong off the bottom.","An Australian test wanted more torque out of turns in deep mud."]}]}],"Honda|CRF250RX":[{"years":[2022,2023,2024],"generation":"2022-2024 (off-road version of the 2022 CRF250R)","summary":"Off-road testers like the RX engine: it pulls low, hits hard in the midrange and lets riders stay in a higher gear on tight trails. Its softer springs and valving are plush and good in rocks, but too soft for grand-prix pace without extra compression. Testers also mention a firm clutch pull, a wide tank and a wish for a sixth gear.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Broad engine that pulls from low rpm, hits hard in the midrange and tolerates being a gear high while still revving.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Too soft for grand-prix speed: the fork wants a few clicks more compression and the shock is soft relative to the fork.","years":[2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer springs and valving are plush on track and trail and excellent in rocks.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch pull feels firm.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Oversized fuel tank is noticeable when putting a leg out.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Five-speed gearbox shared with the motocross bike; off-road testers want a sixth gear.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork dives on big hits at speed","fix":"Stiffen fork compression 1-2 clicks (or more) so it rides higher","result":"Holds up better without losing much plushness","support":2},{"problem":"Harsh in tight rocks","fix":"Soften compression 2-3 clicks at both ends","result":"Smoother in slow technical terrain","support":1},{"problem":"Unstable at speed","fix":"Add sag and lower the forks in the clamps","result":"More stability without giving up much cornering","support":1}],"disagreements":[]},{"years":[2025,2026],"generation":"2025-2026 (2025 frame, airbox and suspension update)","summary":"Little tester data so far. Off-road testers say the RX still pulls low and strong in the midrange, with the off-road map easing the hit, but it signs off on top earlier than some rivals. The stock front tire and the five-speed gearbox are the main complaints.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls low and strong in the midrange; the off-road map softens the transition into the main power, though the top end signs off earlier than some rivals.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock front tire gives poor grip.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Testers still want a sixth gear for off-road.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Fork is a touch soft relative to the shock on big hits.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Arm fatigue on long rides, blamed on the aluminium chassis.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork low under big hits","fix":"Two clicks more fork compression and 104-105 mm sag","result":"Fork held higher in the stroke while staying plush","support":1},{"problem":"Arm fatigue","fix":"Lower triple-clamp pinch-bolt torque and soften fork and shock high-speed compression","result":"Less harshness through the bars","support":1}],"disagreements":[{"topic":"Fork compression direction","sides":["One tester stiffened fork compression to hold it up.","Another softened high-speed compression over several rides for comfort."]}]}],"Honda|CRF450R":[{"years":[2019,2020],"generation":"2019-2020 (2017-generation frame and engine, 2019 update)","summary":"A powerful, light-feeling 450 with a well-liked rider triangle, but testers found the stiff chassis harsh on bumps and inconsistent from day to day. The clutch pull is heavy and the engagement narrow, and riders often calmed the delivery with ECU or exhaust changes. Fork dive under hard braking and an empty-feeling shock on G-outs were the main suspension notes.","points":[{"aspect":"stability","verdict":"weakness","statement":"Stiff chassis feels harsh on bumps and twitchy at speed on rough tracks, and the bike feels different day to day.","years":[2019,2020],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Heavy clutch pull and a narrow, on/off engagement.","years":[2019,2020],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Turns well and feels light; the lower 2020 battery position eases tip-in.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"strength","statement":"Rider triangle widely liked.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"2020 mapping is smoother off the bottom than 2019, but stock maps still deliver too much for anything but loam and roll on jerkily through corners.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork dives under hard braking at race pace; shock feels empty at the end of the stroke on G-outs.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"other","verdict":"neutral","statement":"Traction control helped most testers in slicker afternoon conditions.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Water in the handlebar map switch can stop the bike starting; engine oil darkens quickly.","years":[2019,2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Harsh chassis on square edges","fix":"Lower swingarm-pivot and engine-hanger bolt torque and re-seat the engine (tilted up and back) before torquing","result":"Softer square-edge feel, more rear traction, less vibration and easier initial lean","support":1},{"problem":"Delivery and engine braking upset the chassis","fix":"Aftermarket ECU with linear maps, or an aftermarket muffler with a smoother low end","result":"Less engine braking and pitching; calmer chassis","support":1},{"problem":"Narrow clutch engagement","fix":"Longer aftermarket clutch arm or an auto-clutch style pack","result":"Wider engagement, more clutch life and hook-up","support":1},{"problem":"Fork dive, empty shock","fix":"Stiffer fork compression and slower rebound; shock high-speed compression a quarter turn in at 105 mm sag","result":"Calmer front and better G-out support","support":1},{"problem":"Nervous at speed","fix":"Lower the forks in the clamps (flush or about 2 mm)","result":"Calmer on fast tracks at some cost to turn-in","support":2}],"disagreements":[]},{"years":[2021,2022,2023,2024],"generation":"2021-2024 (all-new 2021 frame; 2023 engine and frame refinements)","summary":"Testers consistently praise this CRF450R's turn-in and rider triangle but call the chassis harsh on dry choppy tracks, nervous at speed and very sensitive to small setup changes. Early 2021 bikes ran rich and popped until Honda's dealer reflash; from 2023 the engine became more linear and torque-led. Stock suspension was the top complaint (soft in 2021, harsh or stagey later), and the most common fixes were revalving or stiffer springs, longer-offset clamps, an aftermarket ECU or exhaust and lower chassis bolt torques. A 1.8 radiator cap is a standard recommendation.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"From 2023 the engine is more linear and torque-led: precise throttle at low rpm, stronger low-mid and a less frantic top.","years":[2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"2021 suspension is soft and unbalanced for fast or heavier riders: the fork pitches and bottoms and the rear blows through in ruts.","years":[2021],"support":4,"strength":"strong consensus"},{"aspect":"mapping","verdict":"weakness","statement":"Early 2021 bikes ran rich and dirty at low rpm, with popping in some maps, until Honda's dealer reflash.","years":[2021],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Sharp turn-in and precise in tight corners.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"weakness","statement":"Harsh and tiring on dry, choppy tracks, loose at the rear on exits and prone to head shake at speed; happiest on smooth tracks.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"balance","verdict":"weakness","statement":"Very sensitive to setup: a few mm of sag or 1 mm of fork height is felt, and a setting does not carry well from track to track.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Standard map (map 1) is the usual choice; the aggressive map is sharper off the bottom but makes less peak power and can ping on hot days.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"2023 frame and steel head stays made the rear calmer and more compliant in corners.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"2022-2024 fork is harsh in the mid or late stroke and the shock is stagey, harsh accelerating out of corners on baked, square-edged tracks.","years":[2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"strength","statement":"Hydraulic clutch has a light, consistent pull and does not fade.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Hydraulic clutch engagement is narrow and on/off, and it is not bulletproof under hard racing.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"At the stock 22 mm offset the front can feel heavy, knife into hooked ruts and oversteer in long rutted corners.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Low-rpm vibration through the pegs and bars.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"strength","statement":"Slim bike with a rider triangle that suits most body sizes; the shift lever is short.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Radiators boil over quickly in hard use.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"A 14-tooth countershaft sprocket can damage the clutch slave cylinder on 2021 bikes.","years":[2021],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Upside-down air filter gets dirty quickly and is awkward to service; seat foam breaks down quickly; exhaust studs can back out.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich, dirty low end (2021)","fix":"Honda dealer ECU reflash; map 3 until then","result":"Cleaner low-rpm running; the fix became the 2022 standard map","support":2},{"problem":"Engine braking and on/off feel upset the chassis","fix":"Aftermarket ECU or a reflash of the stock ECU's maps 2 and 3","result":"Less engine braking, cleaner low-rpm cornering, third gear lugs on stock gearing","support":2},{"problem":"Touchy low end, decel harshness","fix":"Aftermarket exhaust (slip-on or full system)","result":"Smoother low-rpm roll-on, less engine braking and pitching, more mid; one full system with an ECU flash measured about 4.7% more peak power","support":3},{"problem":"Nervous at speed, knifing in ruts","fix":"Longer-offset clamps (23.5-24 mm)","result":"More stability and rut tracking, less vibration and harshness, turning kept","support":2},{"problem":"Head shake","fix":"Lower the forks from 5 mm to about 2.5 mm or flush","result":"Calmer at speed without losing turn-in","support":2},{"problem":"Harsh on square edges","fix":"Lower chassis bolt torques slightly (axle, pivot, hangers) with thread locker","result":"More compliance and traction; Honda responds to this more than other bikes","support":1},{"problem":"Stock suspension soft for heavier or faster riders","fix":"One spring rate stiffer at each end (fork about 5.1 N/mm, shock 56 N/mm)","result":"Rides higher, more traction and track toughness, less oversteer","support":2},{"problem":"Harsh or unbalanced suspension","fix":"Revalve fork and shock","result":"More consistently plush fork and less loose feel at speed; owners name it the top improvement","support":2},{"problem":"Shock harsh accelerating out of corners","fix":"Aftermarket linkage with a flatter early rate and steeper late rate, plus lighter spring and matched valving","result":"Corner-exit harshness roughly halved, better tracking","support":2},{"problem":"Narrow hydraulic clutch engagement","fix":"Fit a 2023 Kawasaki KX master cylinder and flip the stock line","result":"More progressive engagement","support":1},{"problem":"Low-rpm vibration","fix":"Engine tilt procedure when torquing mounts, plus an aftermarket muffler","result":"Reduced vibration","support":1},{"problem":"Boiling over","fix":"1.8 high-pressure radiator cap","result":"Holds coolant in hard use","support":1}],"disagreements":[{"topic":"2021-2022 power character","sides":["One tester found it smoother and longer-pulling than 2020, easy to roll on.","Other tests found a low-rpm stumble and a steep surge around 7,000 rpm that was hard to manage."]},{"topic":"Why the chassis feels harsh","sides":["Testers blamed an overly rigid aluminium frame.","Honda later said the old frame was among the softest and that flex caused the harshness; one tester also found the 2021 frame softer and straighter-tracking than 2020."]},{"topic":"Front brake","sides":["One tester rated it the best brake on a Japanese bike.","Another had it overheat within a few laps in a shootout."]}]},{"years":[2025,2026],"generation":"2025-2026 (stiffer frame with 70% new parts, new linkage and suspension)","summary":"Most testers say the 2025 frame transformed the CRF450R: more planted and stable at speed with less vibration, while keeping its sharp turn-in. The engine is the strongest of its year from low to mid and very usable, but tapers on top and measures a few hp behind the leaders. The plusher suspension suits lighter and slower riders; fast and heavier riders find it too soft and drop the forks, add compression or fit stiffer springs. A minority still report a harsh, kicking chassis on hard, edgy tracks.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Very linear and usable with the strongest low-to-mid pull in its class; can pull third gear in corners.","years":[2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"Much better high-speed stability, less vibration and harsh slap-down, more neutral and less front-heavy in corners.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Tapers off on top; peak power measures a few hp behind the class leaders, though it rides better than its dyno number.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Accurate turn-in, strong on inside lines; it favours tight tracks over fast sweepers.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Coil fork is much plusher with no harsh spot.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Too soft for fast intermediates, pros and heavier riders: the fork dives under heavy braking and can bottom on big jumps, and the softer shock spring suits lighter riders.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"ergonomics","verdict":"strength","statement":"Rider triangle rated best in class.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Shift lever is short and hard to get a boot under.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Brakes are not up to the European bikes' standard.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Three settings each for map, launch and traction control with flash codes and no phone app confuse riders.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Radiator boils over in hard use.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"Stock 13/49 is close; some testers prefer 13/50.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork soft on big jumps and under braking","fix":"Lower forks to about flush-2.5 mm, add 2-3 clicks of fork compression and about half a turn more shock high-speed compression","result":"Better balance and hold-up on big jumps","support":4},{"problem":"Too soft for heavier riders","fix":"Stiffer springs: about 5.1 N/mm fork and 54 N/mm shock over about 190 lb; owners around 180-200 lb report better feel with a stiffer shock spring","result":"More support and better chassis feel","support":3},{"problem":"Fast and pro riders want more support","fix":"Send fork and shock out for firmer valving","result":"Firmer setting suited to pace","support":1},{"problem":"Harsh and unstable on fast hard-pack","fix":"Aftermarket 23.5 mm split clamps","result":"More flex, calmer chassis and better edge comfort; flat-corner exits less planted until the forks were raised","support":1},{"problem":"Harsh chassis feel","fix":"Lower axle, clamp-pinch, pivot and shock-bolt torques slightly with thread locker","result":"More compliance for one tester; owners report only partial improvement","support":2},{"problem":"Boiling over","fix":"1.8 high-pressure radiator cap in place of the stock 1.1","result":"Stopped boil-over","support":1}],"disagreements":[{"topic":"High-speed chassis calm","sides":["Most tests call the 2025-on chassis stable and largely bug-free.","One tester still found it harsh and unstable on fast hard-pack, some owners report a kicking rear on edgy tracks, and one 2026 shootout found it slightly front-heavy in rough high-speed sections."]},{"topic":"Front-end weight","sides":["One shootout called it well balanced since the 2025 frame stiffening.","Another found it slightly front-heavy in rough high-speed sections."]}]}],"Honda|CRF450RX":[{"years":[2019,2020],"generation":"2019-2020 (off-road version of the 2017-generation CRF450R)","summary":"Only one full test in the data. Its strong, throbbing low end defines the bike but is hard to manage in tight terrain, with a stall risk and heat build-up in clutch-heavy riding. Suspension is softer than the motocross bike yet resists bottoming well.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Hits strong and throbbing down low and gets more frantic higher up; hard to control in tight terrain with a constant stall risk.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"A little softer than the motocross bike but takes a big hit to bottom, and bottoming is well controlled.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Starts steaming with long first-gear or clutch-heavy riding on the stock radiator cap.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"First gear is tall for tight trails.","years":[2019,2020],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]},{"years":[2021,2022,2023,2024],"generation":"2021-2024 (off-road version of the 2021 CRF450R)","summary":"Testers call the RX a torque-first engine that is strong but tiring in tight trails. It feels less rigid and more planted than the motocross bike. Complaints include an on/off hydraulic clutch, a wide tank and traction control that helps on dry rocky ground but can bog on loose hills.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Torque-first engine with strong pull; can be tiring in tight trails.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"Feels less rigid and more planted than the CRF450R.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Hydraulic clutch pull is firm and engagement too on/off.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Oversized tank is felt when putting a leg out.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"neutral","statement":"Traction control helps on flat, dry, rocky ground but can make the bike go flat on loose hills.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Softer and less supportive than the KX450X in a cross-country comparison.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Unstable at speed","fix":"Add sag and lower the forks in the clamps","result":"More stability without giving up much cornering","support":1}],"disagreements":[]},{"years":[2025,2026],"generation":"2025-2026 (2025 frame and airbox update)","summary":"Little tester data. The 2025 airbox softened the hit and cleaned up fueling with fewer stalls, and the smooth map with strong traction control makes it feel much milder for long or tight races. Suspension soaks up chatter but is soft for big motocross jumps.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Torque-first delivery with a softer hit, cleaner fueling and fewer low-rpm stalls than before.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Smooth map with the strongest traction setting makes it feel like a 350, good for tight single-track; standard or aggressive suit loam and sand.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Settles further into the stroke and soaks up chatter, but is a bit soft for big motocross jumps.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Unstable at speed","fix":"Add sag and lower the forks in the clamps","result":"More stability without giving up much cornering","support":1}],"disagreements":[]}],"Kawasaki|KX250":[{"years":[2020],"generation":"2020 (last year of the earlier engine, Showa coil fork)","summary":"The 2020 KX250 revs freely with good mid-to-top pull and was one of the most stable 250s, but testers found it short on bottom end compared with the YZ250F and slightly down on low end versus 2019. An ECU remap was the main engine fix. Notes include a grabby rear brake, a tall bar and soft seat, a clutch that slips on hard exits and stock springs that suit a middleweight rider.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Short on bottom-end grunt; needs a downshift more often than a YZ250F and feels slightly weaker down low than 2019.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock springs suit a middleweight: a 140 lb rider found them too stiff in braking bumps, while a 170 lb tester found the fork soft and pitchy on deceleration.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"More mid-to-top pull and rpm recovery than 2019; revs freely.","years":[2020],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"strength","statement":"Straight-line stability and bump absorption among the best in its class.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits low under acceleration and the end of the shock stroke is soft.","years":[2020],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is strong, but the larger rear rotor is grabby and the pedal sits low with a long stroke.","years":[2020],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Stock bar feels tall and wide and the soft seat centre lets the rider sink in.","years":[2020],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch slips on hard exits with good grip.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Wide gap from second to third makes skipping third common.","years":[2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Stock map is conservative and the bike feels weighed down.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak bottom and mid","fix":"Custom ECU map on the stock ECU","result":"Stronger low and mid, freer revving, less engine braking and some exit torque back; quicker laps reported","support":2},{"problem":"Narrow rear tire lacks bite","fix":"110/90-19 rear tire","result":"More bite and stability with no real downside","support":1},{"problem":"Shock low under acceleration","fix":"Sag from 105 to about 103 mm and a quarter turn more high-speed compression","result":"Better traction and front bite; rear held up on G-outs","support":1},{"problem":"Light rider in braking bumps","fix":"Softer fork and shock springs","result":"Better braking-bump comfort; valving was close","support":1},{"problem":"Grabby rear brake","fix":"Fit the 2019 240 mm rear disc and hanger","result":"Easier to modulate","support":1},{"problem":"Tall bar","fix":"Lower-bend bar","result":"Better front feel","support":1},{"problem":"Clutch slip","fix":"Aftermarket clutch basket and pack","result":"No slip and longer life","support":1}],"disagreements":[{"topic":"Which coupler is aggressive","sides":["Most describe white as aggressive and black as mellow.","One tester found white helped low-end recovery but fell off earlier on top, and another magazine called black the most aggressive low-end."]}]},{"years":[2021,2022,2023,2024],"generation":"2021-2024 (big engine update, KX450-based frame, KYB coil fork)","summary":"Testers describe a top-end engine: strong mid and top that revs very high, but weak initial response and low-end torque that hurt corner exits. It is stable in a straight line yet tends to push in flat turns because the engine sits far back in the 450 frame. The KYB fork was widely found stiff and harsh, especially for riders under about 165 lb. Long-term tests list many small quality problems (soft threads, fast-wearing chain rollers, cracking muffler tab), and the usual fixes are fork revalving or lighter springs, an aftermarket linkage, exhaust, ECU mapping and a bigger rear sprocket.","points":[{"aspect":"engine_top","verdict":"strength","statement":"Strong mid and top that revs very high; it rewards being ridden at high rpm.","years":[2021,2022,2023,2024],"support":4,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Weak initial response and low-end torque hurt corner exits; it feels empty after the shift to third in deep dirt.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"KYB fork is stiff and harsh in the midstroke, especially for riders under about 165 lb.","years":[2021,2022,2023,2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"2023 engine has more midrange pull and a stronger top than 2022.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Pushes in flat or off-camber corners and can feel vague mid-corner; the engine sits far back in the frame and the fork rides high.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Soft threads strip easily (airbox bolt, fork-guard bolts, seat nuts).","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Chain rollers, guides and sliders wear quickly; the front roller can come apart around 10 hours.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Coolant loss in sand and a weak stock radiator cap.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"strength","statement":"Stable in a straight line.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Muffler subframe tab cracks at the weld (worse with aftermarket exhaust) and a front engine-mount frame tab can crack after about 50 hours.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Steering-head bearings come with little grease and can fail within 20 hours.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A 2022 long-term bike broke clutch fibres and a main bearing in 75 hours; the 2023 reached 56 hours with no clutch-plate breakage.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Skinny levers cause blisters and the clutch feels on/off; grips are bonded to the throttle tube.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock 100/90 rear lacks bite.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stiff, harsh KYB fork","fix":"Revalve, lighter springs for light riders (about 4.7 N/mm) or remove fork oil","result":"Most of the midstroke harshness removed; one revalve with springs cured about 85-90% of it","support":3},{"problem":"Pushes in flat corners","fix":"Run less sag (about 100-103 mm), sit forward; avoid raising the forks","result":"Weight onto the front and sharper turning","support":2},{"problem":"Rear unsettled or lacking traction","fix":"Aftermarket linkage, with sag reset to about 102-104 mm","result":"Rear more planted and straighter in acceleration bumps, calmer on deceleration","support":2},{"problem":"Weak low end","fix":"Aftermarket exhaust and engine work (porting with ECU mapping)","result":"More bottom and mid pull; some corners taken a gear higher","support":2},{"problem":"Weak low end","fix":"One or two teeth larger rear sprocket (51-52T)","result":"Better pull out of corners","support":2},{"problem":"Wants more midrange","fix":"Custom map using the aggressive coupler's ignition with the mellow coupler's fuel, or Kawasaki's optional map","result":"More midrange and longer pull, noticeable but not huge","support":1},{"problem":"Wants more low response","fix":"Cut the snout off the side panel to open the airbox","result":"Sharper low-end response","support":1},{"problem":"Grabby clutch that burns fibres","fix":"Auto-clutch style pack and a longer-ratio lever","result":"Smoother engagement and longer life","support":1},{"problem":"Steering bearings fail early","fix":"Grease them when new","result":"Normal life","support":1},{"problem":"Narrow rear tire","fix":"110/90-19 rear on the stock rim","result":"More bite","support":1}],"disagreements":[{"topic":"2023 low end","sides":["One tester found more low grunt than 2022.","A magazine found initial response detuned versus 2022, with weaker bottom snap but stronger mid and top."]}]},{"years":[2025,2026],"generation":"2025-2026 (new engine and frame, Showa fork)","summary":"The 2025 KX250 split testers: faster riders found the engine heavier off the bottom with a narrow powerband, little recovery and less over-rev than 2024, while some novice and vet testers found it more usable. The new Showa fork is more compliant than the old KYB but soft for heavier or faster riders. The chassis turns more easily but feels stiffer and less stable at speed. Exhaust, airbox, ECU and gearing changes help response, though owners say it still feels slower-revving than the 2021-2024 bike.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Narrow powerband that feels heavy off the bottom, with little recovery after a mistake and less over-rev than 2024; measured weaker than 2024 above about 6,500 rpm on one dyno.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is soft, sits low and turns harsh for heavier or faster riders, and can feel busy at the top of the stroke on fast tracks.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Turns more easily with better front contact than 2024.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Chassis feels stiffer, twitchy and slightly less stable at speed, deflects and gets nervous when chopping the throttle.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Maps can be changed through the phone app; Kawasaki's optional maps cut engine braking and add low-mid response but shorten the pull in second and third.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Switch to the Showa fork made it far more compliant on corner entry.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"weakness","statement":"Heaviest 250F in one comparison.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Most vibration of the 250Fs despite a new balancer.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Rear brake is hard to modulate and locks easily.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Shifting is notchy under load.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Brittle plastics, a strip-prone airbox bolt, a seat T-plate that can fall out, a low-pressure radiator cap and a restrictive airbox with a hard-to-seat filter.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted intake","fix":"Aftermarket air filter kit and trimming or opening the airbox","result":"Sharper response","support":3},{"problem":"Flat engine","fix":"Aftermarket full exhaust","result":"Stronger mid-to-top pull, smoother over-rev and faster recovery; second held longer and third usable in corners; small low-end gain","support":2},{"problem":"Flat engine","fix":"Stock-ECU reflash or mapped aftermarket ECU","result":"Better response and second-third pull; owners say it still revs slower than the 2021-2024 bike","support":2},{"problem":"Weak pull out of corners","fix":"51-tooth rear sprocket","result":"Better low-end pull","support":2},{"problem":"Oversteer and instability","fix":"Lower the forks to flush (or about 3 mm), run the rear wheel back and speed up rebound","result":"More stable into corners and less oversteer","support":2},{"problem":"Fork too soft for heavier or faster riders","fix":"Revalve with stiffer springs; an aftermarket linkage needs a shock spring about 0.1 kg/mm stiffer","result":"Plush top, firm controlled midstroke, predictable bottoming and a more planted rear","support":1},{"problem":"Stiff, nervous chassis","fix":"Aftermarket engine mounts","result":"More flat-corner lean grip, planted off throttle, better slap-downs","support":1},{"problem":"Weak radiator cap","fix":"1.8 kg/cm2 cap","result":"Holds coolant","support":1}],"disagreements":[{"topic":"2025 engine versus 2024","sides":["Faster riders and two magazines found it heavier, narrower and weaker on top than 2024.","Other launch tests found more usable low-to-mid power and easier starts, and novice and vet riders tended to prefer it."]}]}],"Kawasaki|KX250X":[{"years":[2021,2022,2023,2024],"generation":"2021-2024 (off-road version of the 2021 KX250)","summary":"Off-road testers found the KX250X engine clean and happiest revved, with a strong top but limited bottom-end torque for technical terrain. The small tank, the stock front tire, the bulky kickstand and some head shake at speed were the main complaints. ECU remapping and gearing changes were the common upgrades.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Clean and stall-free down low but short of bottom-end torque for off-road; a remap still left low end lacking.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Strong top end that keeps pulling a long way before the limiter.","years":[2021,2022,2023,2024],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"First gear so short it is rarely used, and fifth runs out quickly.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Small tank ran dry around 55 minutes into a one-hour race.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock front tire has weak traction and stiff sidewalls.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Some head shake at speed; testers wanted a steering stabilizer for fast sections.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Bulky kickstand sits against the left leg.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Heavier vet riders found it under-sprung.","years":[2021,2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Missing low-end power","fix":"ECU remap (one tester also preferred the aggressive coupler)","result":"More power everywhere, though low-end torque was still lacking","support":2},{"problem":"Gearing for desert racing","fix":"Tried 14/48, which was too tall and hard on the clutch in rocks; settled on 14/50","result":"Workable gearing for fast terrain","support":1},{"problem":"Runs out of fuel","fix":"Larger aftermarket tank","result":"Full race distance","support":1},{"problem":"Harsh in slow terrain","fix":"Soften low-speed compression 2-3 clicks at both ends and speed up fork rebound 1-2 clicks at 105 mm sag","result":"Smoother off-road","support":1}],"disagreements":[{"topic":"Bottom-end torque","sides":["Two tests found it short of low-end torque for off-road.","A 2022 test found a decent bottom with enough torque and a linear build."]}]},{"years":[2025,2026],"generation":"2025-2026 (2025 engine and frame, Showa suspension)","summary":"Only one first-impression test. The new engine puts more weight on low and midrange torque, which suits technical riding. The softer Showa suspension is plush in slow terrain but rides low and harsh on deceleration at speed.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"More low and midrange torque than the earlier high-revving engine; easier in technical terrain.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"neutral","statement":"Plush in slow terrain but low and harsh on deceleration at speed.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork low on deceleration at speed","fix":"A few clicks more compression and one click faster rebound","result":"Rode higher in the stroke and more balanced","support":1}],"disagreements":[]}],"Kawasaki|KX450":[{"years":[2019,2020,2021,2022,2023],"generation":"2019-2023 (2019-generation engine and frame, Showa coil fork)","summary":"Testers rate this KX450 chassis among the most stable and forgiving of the aluminium-frame 450s, and it lays into ruts easily, though it can feel long with a vague front. The engine is smooth and usable rather than the strongest, with a touchy hit right off idle. The Showa fork is too soft and divey, the rear brake is grabby, and soft threads and a crack-prone muffler tab are recurring niggles. Stiffer fork springs or a revalve, ECU mapping, a slip-on with the stock header and the KX250's smaller rear rotor were the usual fixes.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"Smooth and very usable rather than the strongest; lacks the mid pull of its main rivals in deep dirt and measures down on power from mid rpm up.","years":[2019,2020,2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Showa fork is too soft: it dives, pitches and bottoms on hills and big jumps, and adding compression only makes it harsh.","years":[2019,2020,2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"Very stable and compliant; frame absorption is among the best in its class and makes setup less critical.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"strength","statement":"Lays into ruts easily with good rear bite and is easy into and through corners.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Can feel long and lazy with a vague front mid-corner and once in a rut.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Touchy right off idle (0-10% throttle), which can upset it mid-corner.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"weakness","statement":"250 mm rear rotor is touchy and locks early.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Soft threads strip (seat nuts, airbox bolt in the subframe).","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock wallows and is soft on slap-downs and G-outs, squatting on exits for heavier riders; the stock link is harsh early and soft deep in the stroke.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"strength","statement":"2021 clutch slips less with wider engagement and more traction.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Muffler mounting tab on the subframe cracks, especially with solid-mounted aftermarket exhausts.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Fork guards and number plates crack and the lower chain roller wears fast.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Skinny clutch and brake levers cause blisters and the clutch feels on/off.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Soft, divey fork","fix":"One step stiffer fork springs (about 5.1 N/mm)","result":"Better balance and decel-bump comfort, less oversteer","support":2},{"problem":"Soft fork and shock","fix":"Revalve (owners say it is valved soft rather than undersprung); one owner raised fork oil volume","result":"Hold-up on deceleration and bump absorption without harshness","support":2},{"problem":"Shock soft on slap-downs","fix":"More shock high-speed compression (up to about two turns in)","result":"Less wallow","support":1},{"problem":"Rear harsh early, soft deep","fix":"Aftermarket linkage, usually with a stiffer shock spring","result":"Plusher early, firmer deep, straighter in acceleration bumps and calmer under braking","support":2},{"problem":"Grabby rear brake","fix":"Fit the KX250's 240 mm rear disc and hanger","result":"Easier to modulate","support":2},{"problem":"Touchy low end, dip from mid to top","fix":"Custom ECU map or reflash; mellow coupler for slick tracks","result":"Smoother off idle, dip filled, steadier in corners; owners call a reflash the cheapest effective upgrade","support":2},{"problem":"Snappy, hard-to-control hit with an aftermarket system","fix":"Slip-on muffler with the stock longer header","result":"Smoother, more controllable power and better corner speed","support":2},{"problem":"Subframe tab cracking","fix":"Rubber-mount the muffler bracket with the stock grommet, or have the tab re-welded","result":"Saves the subframe","support":1}],"disagreements":[{"topic":"Black (mellow) coupler","sides":["One tester found it smoothed the low end with no loss of mid-top pull.","A magazine found it gives up 1-2 hp from 6,000 to 11,500 rpm and is too smooth in deep dirt."]}]},{"years":[2024,2025,2026],"generation":"2024-2026 (new engine top end, frame, Showa suspension and bar electronics)","summary":"Testers agree the stock 2024-on KX450 feels mild and lethargic, more like a big 250 or a 350, with a restrictive airbox (including a hidden rubber plug) and muffler. The new chassis turns in far more sharply but can oversteer and shake its head at speed until the forks are lowered and the wheelbase lengthened. The fork is soft and pitchy with too little initial support. The most common fixes are opening the airbox, an aftermarket ECU and exhaust, a 51-tooth rear sprocket and stiffer fork settings.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Stock engine feels mild, lethargic and heavy in tight corners, soft off the bottom and short on punch for starts, hills and deep sand.","years":[2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Smooth and linear with good mid-to-top pull once revving; best ridden like a big 250.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Much sharper turn-in than before, with front-wheel traction while staying stable.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is soft and pitchy with too little initial support, so it rides in the midstroke, dives under braking, bottoms and feels harsh on deceleration; the shock overpowers it.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"mapping","verdict":"weakness","statement":"Phone-app tuning offers few parameters and small gains, and a custom map saved to the second slot is detuned by the ECU.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Intake and exhaust are restrictive: a hidden rubber plug blocks part of the airbox and the stock muffler is choked.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Can oversteer and shake its head at speed, and feels top-heavy in flat turns.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Second gear is long and third feels far away.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Vibration through the bars at low rpm and the pegs at high rpm.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"weakness","statement":"Measured about 5 lb heavier than the 2023.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Shock is plush, possibly soft for pros, though another tester found it firm in the midstroke and needing more hold-up.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Traction control helps on hard-pack under loose dirt and on uphills but does little on a smooth, dry day.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Some bikes leak oil from the right side-case gasket under the cylinder.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Stock air filter can be mis-installed and collapse inward, risking dirt ingestion.","years":[2024],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A few owners reported very-low-hour engine failures or worn clutch plates around 20 hours; others report no problems.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"Header nuts are nearly inaccessible.","years":[2024,2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Lethargic power","fix":"Aftermarket ECU with tuner mapping, usually with an exhaust and opened airbox","result":"Much stronger off the bottom and third gear usable in corners; one dyno showed almost 4 hp more, and riders felt about 6-7 hp","support":3},{"problem":"Choked intake","fix":"Remove the hidden airbox rubber plug and drill or open the side cover/airbox","result":"Better throttle response and bottom-end pull","support":3},{"problem":"Choked muffler, heavy low end","fix":"Aftermarket slip-on or full exhaust","result":"More response and midrange; one dyno test showed about 3 hp more at 7,500 rpm","support":2},{"problem":"Weak third-gear pickup","fix":"51-tooth rear sprocket","result":"Third more usable in corners","support":2},{"problem":"Oversteer and head shake at speed","fix":"Lower the forks to flush, add a chain link and run the wheel back, add fork compression","result":"More stability at speed","support":4},{"problem":"Soft, bottoming fork","fix":"Stiffer fork springs (one or both legs) or about 10 cc more oil per leg, plus more compression","result":"Better hold-up and bottoming resistance","support":2},{"problem":"Fork and shock lack hold-up","fix":"Shop revalve","result":"More braking-bump support with the same ground-following feel; better shock control on acceleration and landings","support":1},{"problem":"Wants more low torque","fix":"Kawasaki's optional app maps","result":"More low torque feel and second-third roll-on, longer third","support":1},{"problem":"Vibration","fix":"Aftermarket engine mounts and head stays","result":"Less vibration","support":1}],"disagreements":[{"topic":"Top-end strength","sides":["Several tests found good mid-to-top pull.","One magazine found it broad and easy but lacking top end and torque."]},{"topic":"High-speed stability","sides":["2024 tests reported oversteer and head shake at speed.","2026 shootouts called the chassis stable, even best in class, though setup-sensitive."]},{"topic":"Front brake","sides":["One magazine rated the front brake excellent.","A 2026 shootout found it weaker than the class."]},{"topic":"51-tooth rear sprocket","sides":["Magazine testers call it one of the best single changes.","One tester found 13/51 hurt second-gear pull and went back to stock."]},{"topic":"Exhaust and low end","sides":["One magazine's slip-on test showed no meaningful low-end gain.","Other testers felt more low-end pull from slip-ons and full systems."]},{"topic":"Lowering link","sides":["One tester liked a lowering link on the earlier KX450.","On 2024-2025 bikes a tuner advised keeping the stock link because a lowering link softens shock feel; forum riders had no consensus."]}]}],"Kawasaki|KX450X":[{"years":[2021,2022,2023],"generation":"2021-2023 (off-road version of the 2019-generation KX450)","summary":"Testers found the KX450X's softer off-road suspension too soft at speed and on big hits, and stiffened fork compression as a first step. The front can feel vague on lean, the rear brake fades in heat on tight trails and the kickstand gets in the way.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension is too soft at speed: the fork blows through on bigger hits and rides low, and the shock lacks hold-up.","years":[2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"weakness","statement":"Front feels vague on lean and can wash suddenly or push on corner entry; some head shake at speed.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Rear brake fades in heat on tight trails.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Kickstand hits when leaning and stock levers are skinny.","years":[2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork too soft","fix":"Stiffer fork compression and higher oil level, or an off-road revalve","result":"Firmer end of stroke and better hold-up","support":3},{"problem":"Vague front","fix":"Aftermarket 22 mm offset clamps","result":"More front traction, slightly more feedback on fast square edges","support":1},{"problem":"Rear could drive better through square edges","fix":"Aftermarket linkage at 102 mm sag","result":"More traction","support":1},{"problem":"Rear brake fade","fix":"Larger-volume rear brake piston","result":"Holds more fluid and sheds heat","support":1}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024-2026 (off-road version of the 2024 KX450)","summary":"Little tester data. In a cross-country comparison the KX450X felt stiffer with more hold-up than its rival: good on fast courses, harder work in tight rocks and roots. One test noted it ran hot on tight technical trails.","points":[{"aspect":"suspension_front","verdict":"neutral","statement":"Stiffer with more hold-up than its main rival; good on fast courses but harder work in tight rocks and roots.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Ran hot on tight technical trails.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stability on fast cross-country courses","fix":"Rear wheel back about 12 mm with extra chain links, 51-tooth sprocket, forks 2 mm up","result":"Calmer at speed","support":1},{"problem":"Fork soft at higher speeds","fix":"A few clicks more fork compression","result":"Better support at speed","support":1}],"disagreements":[]}],"Triumph|TF 250-X":[{"years":[2024,2025,2026],"generation":"First generation (2024-2026; 2027 update not yet tested)","summary":"Testers rate the TF 250-X chassis as its best trait: light, stable and very good in corners, though the stock KYB setting is soft and aimed at a mid-weight novice or intermediate rider. The 2024 engine bogged on a hard throttle snap and made its power high in the rev range; the 2025 map update reduced but did not fully cure the low-rpm stumble for every tester. Tall gearing, gaps between 2nd, 3rd and 4th and a stiff, notchy gearbox are the most repeated complaints. Common first changes are less rear sag, a tooth or two more on the rear sprocket, a 110 rear tyre and stiffer springs for heavier riders.","points":[{"aspect":"turning","verdict":"strength","statement":"Chassis is light, nimble and stable, with very good corner speed and a forgiving amount of flex; several testers called it the most fun bike in the class to ride in stock form.","years":[2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock KYB setting is soft and plush, suited to roughly 155-175 lb novice and intermediate riders; faster or heavier riders bottom the shock on big landings and the fork dives under hard braking.","years":[2024,2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"mapping","verdict":"strength","statement":"The 2025 fuel map (also a dealer flash for 2024 bikes) cleaned up much of the low-rpm stumble and added measurable power over the 2024 calibration.","years":[2024,2025],"support":4,"strength":"strong consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock 13/48 gearing feels tall with wide 2-3 and 3-4 gaps; most testers went one or two teeth larger on the rear to help third-gear recovery.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"transmission","verdict":"weakness","statement":"Shifting is stiff and notchy, especially into third, with occasional false neutrals; it eases somewhat with break-in.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"2024 engine is crisp just off idle but bogs or stumbles when the throttle is snapped, then dips and surges into the midrange; low end and midrange were its weakest areas against class leaders.","years":[2024],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Power sits high in the range; it works best revved toward the limiter rather than short-shifted, and the gear gaps make that more necessary.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"tires","verdict":"weakness","statement":"Stock Pirelli rear in 100/90-19 on a narrow 1.85 rim limits traction and its carcass rolls or folds under load once worn; a 110 rear is the preferred swap.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"weakness","statement":"On dynos it trails the KTM-family 250s by roughly 1.5-4 hp through most of the midrange and top, landing mid-pack on peak power.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits low under load at the handbook sag, and the shock wants more end-of-stroke support.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"balance","verdict":"neutral","statement":"Bike is sensitive to fork height, sag and shock high-speed compression changes; small adjustments change its balance noticeably.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"The tuning app only loads preset maps; fuel and ignition cannot be edited, which testers see as a limitation versus Japanese tuning apps.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"Motocross testers mostly left traction control off because it dulled the power.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"Weighs in among the lightest 250s on magazine scales.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Torx fasteners throughout mean special tools rather than standard T-handles.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Placed mid-to-low in group shootouts: seventh of eight in one 2025 test, fourth of seven in a 2026 test.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Tends to stand up mid-corner in tight turns, partly blamed on the narrow 100-section stock rear tyre.","years":[2024],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Front can feel busy entering fast, rough corners.","years":[2024],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch can turn notchy, slip under acceleration or drag, attributed to poor oil flow through the stock clutch centre; recall work fits a new hub and plates.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Isolated owner reports of stalling (including off a jump face) and one bike that jumped cam timing after a slow tip-over.","years":[2024,2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rear rides low and bottoms at the handbook 105 mm sag","fix":"Run 100-104 mm race sag and add shock high-speed compression","result":"Rear holds up under throttle and the bike turns more readily","support":5},{"problem":"Soft fork for faster riders","fix":"Add 2-4 clicks of fork compression and run the fork about 3 mm up (or drop it in the clamps on fast tracks to calm a busy front)","result":"More hold-up and better balance; lowering the fork calmed fast rough corners at some cost to turning","support":3},{"problem":"Stock springs too soft for riders over about 80 kg","fix":"Fit Triumph medium or hard spring sets","result":"Bike could be pushed harder with more confidence on jumps and corners, no clicker changes needed","support":3},{"problem":"Tall gearing and gappy 2nd-3rd","fix":"13/49 or 13/50 rear (KTM rear sprockets fit), chain lengthened as needed","result":"Better third-gear recovery and tighter gear spread","support":4},{"problem":"Low-rpm bog on 2024 bikes","fix":"Dealer flash to the 2025 calibration or the richer Akrapovic map","result":"Bog greatly reduced, though the dip-and-surge shape did not fully disappear for every tester","support":3},{"problem":"Wants more corner-exit pull","fix":"Aftermarket full exhaust (FMF or Akrapovic) with matching map","result":"Stronger 2nd and 3rd gear pull and longer midrange; the FMF system softened the initial crack off idle slightly","support":4},{"problem":"Rear traction and mid-corner stand-up","fix":"Swap to a 110-section rear tyre (often Dunlop MX34)","result":"Better traction for most testers; one test felt little change","support":2}],"disagreements":[{"topic":"How completely the 2025 map fixed the low-rpm stumble","sides":["Hesitation and midrange dip removed","Sputter fixed but some bog remains low down"]},{"topic":"Stock suspension balance","sides":["Well balanced out of the box and needing little tuning","Too soft and bottoms easily","Fork slightly stiffer than the shock"]},{"topic":"Preferred stock map","sides":["Map 1 (standard) is stronger in the midrange","Map 2 (soft) preferred and loses little power"]},{"topic":"Quickshifter","sides":["Helps with the stiff gearbox and works well","Ignition cut is distracting, drops out if the lever is not fully lifted, or shifts irregularly"]},{"topic":"Stock gearing","sides":["13/48 felt right at the launch","Too tall; go 1-2 teeth larger"]},{"topic":"Footpegs packing with mud","sides":["Pegs pack with mud","Mud never packed the peg pivot"]}]}],"Triumph|TF 450-RC Edition / TF 450-X":[{"years":[2025,2026],"generation":"First generation 450 MX (2025 RC Edition, 2026 450-X)","summary":"Testers describe the Triumph 450 as smooth and linear rather than brutal: mild off the bottom in the standard map, strong in the midrange and tapering on top, easy to ride over long motos. The chassis earns the most praise for stability and cornering, while the front end can feel vague or light off the throttle. Stock KYB settings are soft and comfortable for a mid-weight rider, though one shootout found the fork harsh and the shock dead. Tall gearing, notchy shifting with false neutrals on early bikes and a vague stock clutch are the recurring complaints.","points":[{"aspect":"sag","verdict":"neutral","statement":"Testers settled at 100-104 mm race sag rather than the 105 mm standard; the 2026 bike was sensitive to small sag measuring errors.","years":[2025,2026],"support":6,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Stable at speed and under braking, good in ruts and strong in corners; one of the best straight-line 450s and the chassis is its best trait.","years":[2025,2026],"support":5,"strength":"strong consensus"},{"aspect":"front_end","verdict":"weakness","statement":"Front end feels light or vague off the throttle and can push in corners; it is harder to lean in than testers wanted.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"gearing","verdict":"weakness","statement":"Stock gearing feels tall and needs extra clutch on tight tracks; a gap between 2nd and 3rd is noticeable.","years":[2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Delivery is smooth and linear rather than aggressive, easy on the rider over long motos and closer in character to the milder Japanese 450s.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"Initial throttle and bottom end feel soft or disconnected in the standard map; testers wanted more bottom-to-mid pull.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Stock KYB setting is soft and comfortable, aimed at a roughly 170-175 lb novice or intermediate; faster or heavier riders use up the travel in rough second motos.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Top end tapers early and over-rev is rough near the limiter, so it works best shifted earlier than most 450s.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Measures competitively on dynos (top of one eight-bike test, third of twelve in another) yet feels milder than its numbers because the curve is so smooth.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"strength","statement":"The Carmichael-developed map on the RC Edition is sharper low down with more hit and pull, and testers preferred it to the standard map.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"transmission","verdict":"weakness","statement":"Early bikes shift notchily under power with false neutrals between 2nd-3rd and 3rd-4th; owners report gearbox parts updated by a service bulletin.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch feels light and vague with a long, soft engagement.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"Among the lightest 450s on magazine scales.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"neutral","statement":"A 20-hour test bike needed nothing beyond oil changes; early bikes had a water-pump whine that faded after break-in.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Fork rides high in its stroke despite being soft, which lets riders run more rear preload.","years":[2025],"support":1,"strength":"single source"},{"aspect":"vibration","verdict":"weakness","statement":"More vibration than most Japanese 450s.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"strength","statement":"A 120-section rear tyre helped the shock keep the rear on the ground.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Tall gearing, 2nd-3rd gap","fix":"One or two teeth larger rear (13/49-13/50, longer chain); heavier owners up to 13/52","result":"Better drive out of turns and improved engine and chassis feel","support":4},{"problem":"Front light or pushing in corners","fix":"Less rear sag (100-102 mm), a few clicks more fork compression, fork raised 1-2 mm","result":"Better front-end tracking in ruts and more bite","support":3},{"problem":"Front hard to feel off the throttle","fix":"Aftermarket triple clamps","result":"Improved off-throttle front-end tracking","support":1},{"problem":"Vague clutch with soft bite","fix":"Aftermarket clutch kit with stiffer spring and extra steel plates","result":"Firmer pull, more bite and shorter engagement; noticeable but not dramatic","support":2},{"problem":"Wants more low-mid pull","fix":"FMF full system or opening the stock muffler baffle","result":"FMF gave longer, stronger midrange in 2nd and 3rd with a softer initial crack; baffle mod gave only a small gain","support":2},{"problem":"Heavier riders (195-240 lb) blowing through the fork","fix":"More fork oil (about 10 cc per leg) or stiffer fork springs, plus slightly stiffer compression and slower rebound","result":"Better g-out and jump-face support","support":2},{"problem":"Notchy shifts and false neutrals on early bikes","fix":"Dealer gearbox update; one owner polished gear dogs and shift-fork parts","result":"Owner reported cleaner shifting; bulletin outcome not yet confirmed","support":1}],"disagreements":[{"topic":"Suspension quality on stock settings","sides":["Plush, good hold-up and balanced for a mid-weight rider","Fork harsh and inconsistent, shock dead (all three testers in one 2026 shootout)"]},{"topic":"Bottom-end character","sides":["Soft off the bottom in the standard map","Standard map snappy and abrupt off the bottom","Good pull from just above idle, usable lugged a gear high"]},{"topic":"Carmichael map","sides":["Sharper with more low-end hit","More controllable and linear than the standard map"]},{"topic":"Stock clutch durability","sides":["Plates lasted about 10 hours","Stock clutch held up over 20 hours"]},{"topic":"Overall standing","sides":["Last of eight in a 2026 shootout","Even with a YZ450F head to head","Would have finished near the front of a 2025 shootout"]},{"topic":"Spring rates for lighter riders","sides":["Stock springs suit a 170-175 lb rider","Riders at or under 170 lb may find stock springs too stiff"]}]}],"Triumph|TF 450-C":[{"years":[2026],"generation":"First generation cross-country (2026)","summary":"Few independent tests exist, all from wet clay woods launches. Testers liked the linear, connected roll-on and midrange, and one found it unusually resistant to stalling at low rpm, while another found little bottom end on tight greasy trail. Traction control split opinion, and two testers ran less sag than standard to help tight turning.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Roll-on is linear and connected, with the midrange as its strength.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"strength","statement":"Traction control raised for slick clay limited wheelspin and kept the rear in check.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"Did not stall at low rpm in tight trail the way most 450s do.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"strength","statement":"Fork resisted bottoming on fast drop-offs and the shock used its full stroke for a 180 lb rider on stock clickers.","years":[2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Engine flamed out at low speed under heavy throttle late in the day, with slow restarts; tester suspected rich mapping.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Slow turning in tight switchbacks","fix":"Run 102 mm race sag instead of the 105 mm standard","result":"More front weight bias and better turning","support":2}],"disagreements":[{"topic":"Low-end strength in tight trail","sides":["Little bottom end; needs revs and momentum","Pulls linearly and does not stall at low rpm"]},{"topic":"Traction control","sides":["Useful on slick clay","Made the throttle feel flat; turned off"]},{"topic":"Race sag","sides":["102 mm for tight woods","108 mm on stock clickers"]}]}],"Triumph|TF 250-C":[{"years":[2026],"generation":"First generation cross-country (2026)","summary":"No independent tester or rider findings were found for the TF 250-C. It shares its platform with the TF 250-X, so 250-X engine and chassis findings are the closest reference, but nothing here confirms how the C-specific suspension and mapping ride.","points":[],"common_fixes":[],"disagreements":[]}],"Triumph|TF 250-E":[{"years":[2026],"generation":"First generation enduro (2026)","summary":"Launch testers found the 250-E pulls cleanly from low revs without stalling, with a strong midrange that lets it hold gears longer. The upshift quickshifter can refuse a shift under hard acceleration. Suspension and clutch impressions were mixed between tests.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Pulls smoothly from low revs without stalling or popping, with a stronger midrange than expected that lets it hold each gear longer.","years":[2026],"support":4,"strength":"strong consensus"},{"aspect":"electronics","verdict":"weakness","statement":"Quickshifter works best at high revs and full throttle and sometimes fails to engage the next gear under hard acceleration.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"strength","statement":"Traction control trims wheelspin rather than cutting power and works well in wet conditions.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"weakness","statement":"On long steep climbs it needed a couple of stops where the 450-E went straight up.","years":[2026],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"Difference between the soft and standard maps is noticeable but not extreme; the soft map suits singletrack.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension","verdict":"strength","statement":"Baseline is firm but not harsh, and most riders can skip a suspension shop.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Handling not settled","fix":"A couple of clicks more compression and 40 mm static sag (set with a KYB technician)","result":"Calmer handling","support":1}],"disagreements":[{"topic":"Clutch feel","sides":["Excellent, can lug up a hill with one finger","Heavy clutch pull"]}]}],"Triumph|TF 450-E":[{"years":[2026],"generation":"First generation enduro (2026)","summary":"Testers describe the 450-E as linear, controllable and easy to lug, with a strong midrange and a light, almost 350-like feel. The main chassis complaint is a fork that is softer than the shock and dives on braking or at speed, which several testers balanced by lowering the rear. The rev limiter is abrupt and the quickshifter can balk under hard acceleration.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Delivery is linear and controllable with a broad torque spread; it lugs well and feels lighter than its size.","years":[2026],"support":5,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"The soft map is noticeably smoother and suits casual trail riding or mud, while the standard map suits racing.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork is softer than the shock and dives on hard braking or reaches its limits at speed on rough ground.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Midrange is its standout and pulls harder than a typical trail bike.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"weakness","statement":"Quickshifter sometimes fails to engage the next gear under hard acceleration.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"electronics","verdict":"strength","statement":"Traction control keeps slip low in wet conditions.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock rebound is a little fast and the rear could use more bottoming resistance in big high-speed whoops.","years":[2026],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"weakness","statement":"Rev limiter is abrupt and buzzes the pegs and bars.","years":[2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"strength","statement":"Stock 13/51 gearing with six well-spaced ratios felt about right.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Fork dives and the bike sits nose-down","fix":"Lower the rear (race sag 105-108 mm), add fork compression and slow fork rebound","result":"Bike levels out and the front holds up better","support":3}],"disagreements":[{"topic":"Suspension baseline","sides":["Firm but not harsh, or balanced and compliant","Fork too soft for fast riding"]},{"topic":"Race sag","sides":["102 mm as recommended by KYB","105-108 mm to level the bike"]},{"topic":"Map choice in the wet","sides":["Soft map plus traction control","Full-power map, since traction control already limits slip","Soft map too soft low down"]},{"topic":"Clutch feel","sides":["Excellent","Heavy pull"]}]}],"Suzuki|RM-Z250":[{"years":[2019,2020,2021,2022,2023,2024,2025],"generation":"2019-2025 generation (pool covers 2019, 2020, 2024)","summary":"Testers agree the RM-Z250 is sprung and valved too stiff at both ends for most riders, and that its engine has a good bottom but fades through the mid and top. Once the suspension is softened it is rated one of the best-cornering 250Fs. It sits at the back of recent shootouts and was lowest on one dyno comparison. Reported reliability on a hard-raced project bike was good.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Fork and shock are too stiff for most riders, deflecting on dry chop; testers wanted a spring rate softer at each end.","years":[2019,2020,2024],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"weakness","statement":"Good, snappy bottom end but power flattens through the mid and signs off on top, forcing short shifts.","years":[2019,2020,2024],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Finishes last in recent 250 shootouts.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Lowest peak power of eight 250s on one 2025 dyno comparison.","years":[2025],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"Among the best-cornering 250Fs once the springs are softened; suits front-end steerers.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Rear sits high and stiff, costing rear traction.","years":[2020],"support":1,"strength":"single source"},{"aspect":"stability","verdict":"weakness","statement":"Chassis feels stiff on chop and slap-downs.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"White coupler is the most aggressive, freer-revving map; grey feels rich and smooth.","years":[2020],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"strength","statement":"Brakes stay controllable with no fade over long hill sessions.","years":[2020],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch slips under heavy load.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"Hard-raced project bike had no issues.","years":[2019,2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Suspension too stiff, harsh on chop","fix":"Softer springs (about 4.9 N/mm fork, 50 N/mm shock) or a revalve with lighter springs; 108 mm sag","result":"More compliance, calmer chassis, better turning and stability","support":2},{"problem":"Flat midrange and weak top","fix":"Aftermarket exhaust, or porting, valve job and ECU work","result":"Better character; about 10% more mid-top on the dyno with the engine work","support":2},{"problem":"Feels air-starved when ridden hard","fix":"Cut the airbox snorkels and open the airbox edges","result":"Better response and pull everywhere; louder and dirtier filter","support":1},{"problem":"Stiff chassis on chop","fix":"4 mm hole drilled in the upper engine mounts","result":"Softer over chop and slap-downs with more front bite","support":1},{"problem":"Clutch slip under load","fix":"Aftermarket clutch pack","result":"Hooks up and lightens the pull","support":1}],"disagreements":[]}],"Suzuki|RM-Z450":[{"years":[2018,2019,2020,2021,2022,2023,2024,2025,2026],"generation":"2018-2026 generation (pool covers 2020-2026)","summary":"The RM-Z450 is consistently praised for cornering: it leans in easily and holds ruts. The air-free BFRC shock is the most repeated complaint, being hard to set up, harsh in the rough and prone to riding high off the throttle, and the coil fork also wants softening or a revalve. The engine fades on top and rewards short shifting, most testers add a tooth to the rear sprocket, and it is the heaviest 450 with no electric start or hydraulic clutch.","points":[{"aspect":"turning","verdict":"strength","statement":"Leans into corners easily, holds ruts well and has a sharp turn-in.","years":[2020,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"BFRC shock is hard to dial in, harsh in rough conditions, and rides high or kicks off the throttle into corners.","years":[2020,2021,2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Showa coil fork is stiff and benefits from softer compression or a revalve.","years":[2024,2025],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"Rigid chassis gives head shake in successive chop and at speed in rough sections.","years":[2020,2021,2024,2025],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Fades on top and revs out quickly, so it works best short-shifted.","years":[2020,2024,2025],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"weakness","statement":"Heaviest 450 on magazine scales.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"features","verdict":"weakness","statement":"Kick start only, with a cable clutch rather than hydraulic.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"neutral","statement":"Mid-to-lower pack on a 2026 twelve-bike dyno comparison.","years":[2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Stock clutch fades quickly and has a narrow engagement.","years":[2021],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is powerful but grabby.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Cold-blooded and rich for the first lap.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"30+ hours on a 2025 bike with only routine maintenance, though a 2021 test bike leaked a shock seal early.","years":[2021,2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Bogs or wants third gear sooner out of turns","fix":"One tooth larger rear (13/51 instead of 13/50), or one to two teeth","result":"Better drive out of tight turns","support":3},{"problem":"Shock rides high off throttle and the bike knifes on entry","fix":"Lower the rear with longer link arms and about 107 mm sag; some testers swap in the RM-Z250 shock","result":"Calmer corner entry and firmer initial stroke","support":2},{"problem":"Head shake in chop","fix":"Lower the rear and raise the front, add fork flex with softer-flexing clamps, or a fork revalve","result":"Settled corner entry and less head shake","support":2},{"problem":"Stiff fork","fix":"Two clicks softer compression","result":"Noticeably better","support":1},{"problem":"Lethargic power","fix":"Full exhaust system","result":"Cleaner, longer pull; no extra bottom end","support":1},{"problem":"Lacks bottom pull","fix":"Slip-on with insert, higher-compression piston, optional aggressive map","result":"More bottom and exit pull","support":1},{"problem":"Clutch fade","fix":"Full aftermarket clutch kit","result":"Firmer feel and longer plate life","support":1},{"problem":"Coolant loss in long motos","fix":"Higher-pressure radiator cap","result":"Stopped the loss","support":1}],"disagreements":[{"topic":"Bottom-end strength","sides":["Strong low end with best pull 7,000-8,800 rpm","Lacks bottom pull and recovers slowly a gear high"]}]}],"Yamaha|YZ250F":[{"years":[2019,2020,2021,2022,2023],"generation":"2019-2023 reverse-head engine, electric start","summary":"Testers treat this generation as the low-to-mid torque specialist of the 250F class: it pulls almost like a bigger bike out of corners and lets riders carry a higher gear, but it runs out of revs earlier than the European bikes, so it needs more shifting. The KYB spring fork is well liked, though it softens after break-in and dives on corner entry for faster or heavier riders. Off-throttle engine braking pitches the chassis, and most testers load a less-engine-braking or top-end map in the app. Recurring owner complaints are a cramped cockpit for tall riders, seat foam that packs down, a soft front brake and an air filter that does not seal well.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong bottom-to-mid torque for a 250F; riders can corner a gear higher than on rival bikes.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Runs out of pull and over-rev earlier than the KTM-group and Honda bikes, so riders shift more.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"The KYB spring fork is rated among the best stock forks and handles big whoops well.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Once broken in the fork goes soft and dives into flat corners and under braking for faster or heavier riders.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"strength","statement":"Planted, predictable chassis that tracks straight and turns point-and-shoot; less agile than the KTM but forgiving, with a frame that flexes well.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake feels mushy or spongy from the factory.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Air filter does not seal well; dirt collects at the back of the airbox. The 2020 filter grommet helped but did not fully cure it.","years":[2019,2020],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"The 2021-2023 engine lost a little bottom-end roll-on compared with 2019-2020 while revving more freely.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"Noticeable engine braking makes the chassis pitch on corner entry at stock settings.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"weakness","statement":"Stock maps feel abrupt for average riders, and a slight hesitation at the first crack of throttle in slow ruts remained even after remapping on the 2023.","years":[2021,2023],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"At about 105 mm sag the shock balances riders from roughly 150 to 195 lb with good rear traction.","years":[2020],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"The 2022 update added low-speed fork damping, giving more hold-up, less pitching and better braking-bump compliance.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Cockpit is cramped for riders around 5'10 and taller, and seat foam packs down within 10-20 hours.","years":[2019,2020,2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Stock muffler packing goes raspy after about 10-20 hours.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Stock lithium batteries failed on a test bike and left the tester stranded.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"A few owners reported cam chain failures on 2019-2020 bikes; the sample is small.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A few owners tied hard starting, stalling and fouled plugs to the idle setting.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Cable clutch heats up under hard use and needs free play adjusted between motos.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Some bikes have too much throttle free play even with the adjuster fully out.","years":[2019,2020,2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Chassis pitches on corner entry from engine braking","fix":"Load a less-engine-braking (free-revving) map in the Power Tuner app","result":"Less decel pitching, lighter mid-corner feel and a little more top end","support":1},{"problem":"Runs out of pull on top","fix":"Tuner or factory map aimed at mid and top end","result":"More pull through 2nd and 3rd and the next gear lands in the power; 13/51 stopped forcing short shifts","support":2},{"problem":"Low-to-mid lacks punch on stock exhaust","fix":"Full aftermarket exhaust system","result":"More low-to-mid pull and smoother pull through the gears; top end about the same","support":2},{"problem":"Throttle response and pull","fix":"Vent the airbox lid (drilled holes or vented cover)","result":"More pull and response; intake noise goes up and the filter gets dirtier faster","support":2},{"problem":"Wants more top end and over-rev","fix":"Ported head or engine kit (factory accessory kit or dual-injector setup)","result":"Stronger top-end surge and over-rev, with slightly less low-end response on one kit","support":2},{"problem":"Fork dives and front washes in flat corners","fix":"Stiffer 4.8 N/mm fork springs or 5 cc more fork oil","result":"More hold-up, less pitching and a calmer front under braking","support":1},{"problem":"Cramped rider triangle","fix":"Lower and rearward footpeg mounts (about 5-7 mm down and 5 mm back)","result":"More room for riders 5'8 to 6'2 without losing ground clearance","support":1},{"problem":"Spongy front brake","fix":"Swap to an older KTM Brembo master cylinder with the stock Yamaha caliper","result":"Firmer, more powerful front brake","support":1}],"disagreements":[{"topic":"Where the stock engine is strongest","sides":["Most tests call it the strongest low-to-mid engine in the class","One exhaust test found stock weaker from idle to about 10,000 rpm and stronger only above that"]},{"topic":"Stock shock","sides":["The shock balances a wide rider weight range with good traction","Another test found the shock wallows and turned rebound in"]}]},{"years":[2024,2025,2026],"generation":"2024-2026 YZ450F-based frame and bigger airbox","summary":"The 2024 update moved the YZ250F to a slimmer frame based on the YZ450F, with a bigger, lower airbox. Testers agree it lost low-end snap: there is a lag off the bottom and riders need clutch, while the mid and top got stronger. Tuners blame the larger airbox. The chassis turns and tips into ruts more easily but felt busier at speed, and the 2024 fork was soft and dived. The 2025 linkage and shock changes calmed it. Alternative app maps such as the factory 'Response' map are the usual way to bring back the bottom end, and the bike is loud.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Weaker, laggy bottom end compared with 2023; slower riders need clutch to get into the power and it can bog a gear too tall.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"mapping","verdict":"strength","statement":"Alternative app maps (the factory 'Response' map, test-rider and tester maps) bring back low-end response; the 2025 standard map already feels like the 2024 'Response' map.","years":[2024,2025,2026],"support":4,"strength":"strong consensus"},{"aspect":"noise","verdict":"weakness","statement":"Loud and raspy when revved, with intake noise from the bigger airbox.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"Feels slim and light, turns and tips into ruts very easily, with more frame feedback.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2024 fork is soft: it dives in corners and under braking and blows through on big hits, and the bike pitches.","years":[2024],"support":3,"strength":"strong consensus"},{"aspect":"balance","verdict":"strength","statement":"The 2025 linkage and settings cut fork dive and pitching, hold the bike higher in the stroke and give a more planted rear.","years":[2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Stronger mid and high-rpm pull with the best over-rev this engine has had; suits fast riders who keep it revved.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"neutral","statement":"Tuners link the softer low end and heavier engine-braking feel to the larger, lower-velocity airbox.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"Leaves a gap between 2nd and 3rd gear; needs more shifting and corner speed.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"The 2024 front end feels busy or twitchy on fast, rough straights, and the chassis is stiffer and less comfortable than before.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"Cable clutch heats up and needs free play adjusted during or between motos.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"About 3 lb lighter than the 2023.","years":[2024],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"neutral","statement":"Cockpit is roomier than 2023 with a flatter seat and lower, rearward pegs, yet riders 5'10 and up still found it cramped.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"mapping","verdict":"neutral","statement":"On the 2025, testers preferred the standard map; the performance map added mid and top but took away too much bottom.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"The 2024 shock wallows.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Even on 2024-2026 bikes the fork reacts too quickly when loading the front in corners and the front can wash; the rear sits high for riders under about 160 lb.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"The stock filter let dirt into the intake on a test bike; testers fitted an aftermarket filter and cage.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake still feels spongy.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"Owner reports on 2024-2025 bikes show no pattern of engine failures so far.","years":[2024,2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"Stock Yamaha wheels ranked toughest of the OEM wheelsets tested.","years":[2025],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"neutral","statement":"On one tuner's dyno the 2025 was 6th of 8 for peak power and lowest for torque, with the latest torque peak; the magazine noted its part-throttle feel on track is better than the numbers suggest.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Weak low end","fix":"Load the 'Response' preset or a test-rider/tester map","result":"Low end comes back, revs can drop and 3rd works in corners; 'Response' hits a little harder","support":3},{"problem":"Low-end lull and long 2nd-to-3rd gap","fix":"One tooth smaller rear sprocket (50 to 49) to lengthen the gears","result":"Helped the lull but did not fix it","support":2},{"problem":"Fork dives and blows through (2024)","fix":"2-3 clicks more fork compression, raise fork tubes about 2.5 mm, or a stiffer revalve","result":"Less dive and more hold-up; one revalve for intermediate/pro riders removed wallow, though vet testers preferred stock","support":3},{"problem":"Front tips in too quickly","fix":"Slide the fork tubes down a few millimetres in the clamps","result":"Calmer turn-in","support":1},{"problem":"Front twitchy at speed","fix":"Aftermarket clamps at 23 mm offset (stock 22)","result":"Calmer entry on choppy ground and less head shake; 22 mm in the aftermarket clamps gave more front traction","support":1},{"problem":"Low-end response","fix":"Fit a 2023-24 YZ450F airbox with a remapped aftermarket ECU","result":"Better low-end pickup and more pull through 2nd-4th; 3rd usable in corners","support":1},{"problem":"Low-end response","fix":"Vented airbox lid","result":"More low response and mid punch; much louder intake","support":1},{"problem":"Fork too quick in corners, rear high for light riders","fix":"Slower rebound both ends and softer shock high-speed compression for riders under 160 lb","result":"Calmer chassis; rear squats on exits and the fork settles on braking bumps","support":1}],"disagreements":[{"topic":"Top-end strength in class","sides":["Testers found the top end strong and the best over-rev Yamaha has made on this engine","A 2024 shootout found it still could not match the KTM, Husqvarna, Kawasaki or GasGas at high rpm"]},{"topic":"2024 stability","sides":["Some testers found the front busy and twitchy at speed","Another test found it nimble with no stability issues"]},{"topic":"Intake noise","sides":["Several tests call the airbox loud","One launch tester found it quieter than before at lower revs"]}]},{"years":[2027],"generation":"2027 all-new (YZ450F-based)","summary":"Only launch impressions exist so far. One heavier tester found it slightly soft right off the bottom but pulling harder and longer as revs rise, turning in willingly, with stock suspension soft over braking bumps for his weight. Another tester's setting changes were aimed at bigger jump landings.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"A touch soft right off the bottom; an accessory intake and a more aggressive map sharpen it.","years":[2027],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"strength","statement":"Pulls harder and longer as revs rise, past where riders expect the limiter.","years":[2027],"support":1,"strength":"single source"},{"aspect":"turning","verdict":"strength","statement":"Turns in willingly and holds lines.","years":[2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension felt soft over braking bumps for a heavier rider.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|YZ450F":[{"years":[2018,2019,2020,2021,2022],"generation":"2018-2022 electric-start generation","summary":"Testers liked this generation's engine on the track: broad, linear power with strong pull, though the first crack of throttle can be abrupt and most testers loaded a smoother preset such as the TP map. From 2020 it felt mellower below about 9,000 rpm with lighter engine braking and a more precise chassis. The 2018-2019 felt twitchy at speed. The KYB suspension was praised for comfort across a wide rider weight range, and the cable clutch for its light pull. Recurring complaints were cramped ergonomics for tall riders, seat foam that packs down, an air filter setup that lets dirt in and slow hot restarts.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Smooth and linear overall, but the first crack of throttle is abrupt or jerky, especially on hard-pack.","years":[2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Most testers run a smoother factory preset (the TP map) or a mellower custom map instead of the stock map.","years":[2018,2019,2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"KYB suspension is comfortable and resists bottoming across a wide rider weight range; most testers stayed close to stock.","years":[2018,2019,2020,2021,2022],"support":4,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"neutral","statement":"From 2020 the engine feels mellow below about 9,000 rpm and does its best work above it, with lighter engine braking so it coasts into corners.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"strength","statement":"The 2018-2019 engine had a long usable powerband with strong low end and top end and the best throttle response in its class.","years":[2018,2019],"support":3,"strength":"strong consensus"},{"aspect":"handling","verdict":"strength","statement":"From 2020 the chassis feels more precise, agile and lighter, while still steering mainly from the rear.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Cramped for tall riders, with bars high and seat low on 2018-2019 and a firm seat that packs down.","years":[2018,2019,2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_mid","verdict":"neutral","statement":"On magazine dynos it often trails rivals from about 6,000 to 8,000 rpm and comes alive late, even when peak power is competitive.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"stability","verdict":"weakness","statement":"The 2018-2019 felt twitchy and loose at speed and on corner exit compared with the KTM.","years":[2018,2019],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"weakness","statement":"Feels heavy or vague landing into a lean compared with the KTM and Husqvarna; magazine scales put it 15-17 lb heavier than the KTM.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"strength","statement":"The cable clutch was rated the best non-hydraulic clutch in the class with an easy pull.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"brakes","verdict":"neutral","statement":"The 2018-2019 brakes had weak initial bite and then grabbed; the 2020 Nissin front is much stronger and touchier.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Air filter setup lets dirt in: the flat filter dries on the backfire screen, and without the screen dirt can drop into the boot during filter changes.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"reliability","verdict":"weakness","statement":"Slow hot restarts after a stall and quick overheating at idle.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"The wrap-around exhaust is hard to remove and intake noise is loud.","years":[2018,2019,2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"strength","statement":"Won a 2020 450 bracket shootout and was ranked first or second by every tester in another.","years":[2020],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"Spools up fast and spins or wheelies out of hard-pack corners; mapping alone did not fix it.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Once broken in, the fork dives off throttle and is slightly soft on big bumps at speed.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"weakness","statement":"The 2020 shock squats and sits low under throttle, with a harsh mid-stroke.","years":[2020],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"One test bike went 100 hours with basic maintenance.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Abrupt low-end hit","fix":"Run the smoother TP 3.0 preset or another softer factory map","result":"Linear, easy roll-on that pulls longer; also good for starts","support":3},{"problem":"Abrupt low end for experienced riders","fix":"Ride one gear higher on the stock map","result":"Softens the hit and engine braking and avoids stalling","support":2},{"problem":"Wheelspin on hard-pack exits","fix":"Heavier steel clutch basket","result":"Calmer exits and less wheelspin, with slightly more engine braking","support":1},{"problem":"Rear squats under throttle","fix":"Longer aftermarket link arm plus softer high-speed compression","result":"Flatter decel, better exit traction; firmer if ridden lazily","support":1},{"problem":"Fork dives and shock squats","fix":"Revalve on stock springs","result":"More fork hold-up without deflection, firmer shock that squats less","support":1},{"problem":"Cramped for tall riders","fix":"Taller seat and lower/rearward footpegs","result":"Better attack position and easier sit-to-stand","support":2},{"problem":"Air intake","fix":"Domed filter kit and raised airbox lid, optionally with a tuner map","result":"About 2 hp more at peak and more over-rev on one magazine dyno","support":1},{"problem":"Chassis unsettled on acceleration and braking","fix":"Change gearing from 13/49 to 14/53","result":"Chassis settles and 3rd stays usable","support":1}],"disagreements":[{"topic":"Engine strength vs rivals","sides":["A tester's head-to-head found it ahead of the KX450 at low, mid and top","Magazine dynos put it near the bottom of the class from 6,000 to 8,000 rpm"]},{"topic":"Best map choice","sides":["Most testers preferred the TP preset or a mellower map","One magazine preferred the new 2020 stock map on loose, good-traction tracks"]},{"topic":"Aftermarket exhaust","sides":["One test found both aftermarket systems lost some over-rev against a very good stock system","Other tests found full systems smoothed roll-on and added mid and top"]}]},{"years":[2023,2024,2025],"generation":"2023-2025 all-new engine and frame","summary":"Testers rate this engine among the strongest in the class, but the first crack of throttle is very sharp: it wheelies and breaks traction, and most testers detune it with a richer low-rpm map, a flywheel weight or a smoother exhaust. The 2023-2024 chassis turns sharper than any earlier YZ450F but gives up straight-line stability, with head shake and oversteer. The 2025 linkage and mount changes calmed it for most testers. Recurring complaints are a cable clutch that fades, a thin hard seat, dirt getting past the filter cage and a loud intake.","points":[{"aspect":"power_delivery","verdict":"weakness","statement":"Very sharp first crack of throttle: it pops out of ruts, wheelies and breaks traction; most riders need it detuned.","years":[2023,2024,2025],"support":5,"strength":"strong consensus"},{"aspect":"mapping","verdict":"neutral","statement":"Testers detune it with a richer low-rpm or smoother map; a fully softened map still revs past 11,000 rpm.","years":[2023,2024,2025],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"strength","statement":"Very strong, linear pull through the mid and top with a long over-rev; among the most powerful engines in the class.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"weakness","statement":"Less stable at speed: aggressive turn-in, front-end oversteer and head shake, plus harshness at the edge of the tire.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Seat is thin, domed and stiff, breaks down within about 8-10 hours, and the side panel catches boots.","years":[2023,2024,2025],"support":3,"strength":"strong consensus"},{"aspect":"turning","verdict":"strength","statement":"The sharpest-turning YZ450F yet, feeling lighter and more agile than 2022.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"balance","verdict":"strength","statement":"The 2025 linkage, mounts and springs make it more planted and less twitchy, with less pitching.","years":[2025],"support":2,"strength":"consensus"},{"aspect":"suspension_rear","verdict":"weakness","statement":"Shock is stiff on high-speed compression relative to a softer fork; on 2023 it also sat low on big hits.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"clutch","verdict":"weakness","statement":"The disc-spring cable clutch fades or slips under hard use and its spring is too soft; plates last 10-12 hours for a rider who covers the clutch.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"On 2023-2024 the map button sits where the kill button gets pressed, and the throttle position causes thumb blisters.","years":[2023,2024],"support":2,"strength":"consensus"},{"aspect":"maintenance","verdict":"weakness","statement":"Dirt can get past the filter cage at the front edge, and pulling the filter lets dirt drop into the intake.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"noise","verdict":"weakness","statement":"Loud intake roar from the front airbox.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"weight_feel","verdict":"strength","statement":"About 5 lb lighter than the 2022 on magazine scales.","years":[2023,2024,2025],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"The softer 2025 fork springs suit vets and novices, but fast testers found the front too soft.","years":[2025],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2023 front end is light in shallow ruts and pushes when setting up wide.","years":[2023],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Even with the lower, rearward pegs the cockpit is cramped for riders 5'10 and up.","years":[2023,2024,2025],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"2nd and 3rd gear are poorly spaced for some riders.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Several consumer 2025 bikes broke connecting rods.","years":[2025],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"Stock Yamaha wheels ranked toughest of the OEM wheelsets tested.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Abrupt low end","fix":"Richer map below about 5,000 rpm, often with a 48-tooth rear sprocket","result":"Calmer exits; taller 2nd pulls longer before 3rd","support":1},{"problem":"Spools fast, wheelies and spins","fix":"Flywheel weight (about 80 g)","result":"Calmer power build, more traction and better lugging without extra engine braking","support":1},{"problem":"Harsh initial hit","fix":"Aftermarket slip-on or full exhaust","result":"Smoother, more linear low end and better rear traction, revving out about as far as stock","support":3},{"problem":"Head shake and oversteer at speed","fix":"Slide forks down in the clamps, snug the steering stem slightly, or fit 23 mm offset clamps","result":"Calmer steering and straighter tracking","support":1},{"problem":"Unstable on braking bumps","fix":"Aftermarket engine mounts","result":"Calmer over braking bumps and more front feel on throttle, slightly heavier turn-in","support":1},{"problem":"Clutch fade","fix":"Factory-accessory hydraulic clutch kit or an aftermarket basket and spring kit","result":"Lighter pull, more consistent engagement and starts","support":2},{"problem":"Rear squat and empty feel under load","fix":"Aftermarket linkage with sag reset to 104-105 mm","result":"Better rear traction and comfort","support":1},{"problem":"Air intake","fix":"Domed filter kit plus a vented airbox cover","result":"Over 2 hp gained and quicker revving; much louder","support":1}],"disagreements":[{"topic":"2025 stability","sides":["One review found the 2025 more planted and less twitchy at speed","A race test still found head shake at speed and tuck on entry until clamps and fork height were changed"]},{"topic":"Factory smooth map","sides":["One magazine's testers mostly chose the factory Smooth Linear map and kept it","Another found it did not tame the low end enough and built a richer custom map"]},{"topic":"Gearing direction","sides":["One magazine went to a 48-tooth rear to soften exits","A tester went to 13/50 on deep East Coast dirt to recover 2nd and reach 3rd sooner"]}]},{"years":[2026],"generation":"2026 update (intake, flywheel, hydraulic clutch, frame stiffness)","summary":"Testers found the 2026 smoother, quieter and easier to ride than 2025, but it gives up some low-rpm snap and peak power and ranked mid-pack or lower on shootout dynos. Several shootouts still rated it highly because the chassis is more stable and balanced than 2023-2025 while turning precisely, although it carves deep ruts and flat turns less well than the best rivals. The fork is the main setup issue: testers found it harsh in the mid-stroke but disagreed on why. The 51-tooth stock rear sprocket makes 2nd gear very short.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Feels more plugged up or choked down low than 2025 and gives up some peak and quick revving.","years":[2026],"support":4,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork feels harsh or stiff in the mid-stroke and can overpower the shock, hurting front traction.","years":[2026],"support":4,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"neutral","statement":"Ranked mid-pack or lower on shootout dynos (about 54-57 hp), roughly 3 hp below the 2025 on one magazine's dyno.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"stability","verdict":"strength","statement":"More stable and balanced than 2023-2025 while still turning precisely.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"gearing","verdict":"weakness","statement":"The stock 51-tooth rear sprocket makes 2nd gear very short and 3rd can struggle in some corners.","years":[2026],"support":3,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Smoother and easier to ride, with a more linear low-mid and a broader peak.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"turning","verdict":"weakness","statement":"Slides through flat turns more than it carves; weaker in deep ruts and flat-turn traction than the best rivals.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"ergonomics","verdict":"weakness","statement":"Round seat, tall feel and side panels that catch boots.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"vibration","verdict":"strength","statement":"Little to no vibration; least in one 2026 shootout.","years":[2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"weakness","statement":"More engine braking than 2024-2025 makes it harder to roll corners and upsets the chassis on entry.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"strength","statement":"Shock is much better than the 2025.","years":[2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"strength","statement":"The new hydraulic clutch is lighter and needs no mid-moto adjustment.","years":[2026],"support":1,"strength":"single source"},{"aspect":"noise","verdict":"strength","statement":"Noticeably quieter than 2023-2025.","years":[2026],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"weakness","statement":"Exposed stator wire and clutch line, and a low-pressure radiator cap.","years":[2026],"support":1,"strength":"single source"},{"aspect":"suspension_rear","verdict":"neutral","statement":"Owners around 230 lb say it needs heavier springs.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"2nd gear too short","fix":"Go from 13/51 to 13/50","result":"Usable 2nd for vet riders and 3rd comes in easier; fast riders kept 51","support":2},{"problem":"Engine feels choked","fix":"Fit a 2025-style accessory airbox or raised intake cover with a freer aftermarket or 2025 exhaust","result":"Stronger, more responsive feel with clearer bottom-end gain","support":2},{"problem":"Engine braking upsets corner entry","fix":"App map that relaxes the engine on deceleration","result":"Better corner-entry balance","support":1},{"problem":"Low end lacks excitement","fix":"Optional test-rider or tester maps","result":"More low-end excitement or exit connection","support":1}],"disagreements":[{"topic":"Why the fork feels harsh","sides":["One shootout found it stiff early and overpowering the shock; the fix was raising the fork 2-5 mm and softening compression","A race test found it was actually too soft and riding low where damping ramps up; more shock sag plus 2 clicks stiffer fork compression made it plusher"]},{"topic":"Turning","sides":["One magazine said the new frame turns with less effort","Another shootout found it weaker carving flat turns and ruts"]}]},{"years":[2027],"generation":"2027 update","summary":"Only one day-one magazine test so far. On paper the 2027 fork is softer, but testers found it rode higher in the stroke and harsher than the 2026, and they softened fork compression.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Fork rides higher in the stroke and feels harsher than 2026 despite softer specs; testers went 2 clicks softer on compression, and slower riders raised the forks 5 mm.","years":[2027],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|YZ450FX":[{"years":[2019,2020],"generation":"2019-2020","summary":"One outlet tested this generation. Testers found it strong and smooth off the bottom, hard to stall and free-revving, with a plush, stable chassis. On the 2019 the clutch lost bite on sudden release.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Strong, smooth bottom end that is hard to stall, then lively and free-revving through the mid and top.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"handling","verdict":"strength","statement":"Plush and stable chassis.","years":[2019,2020],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch lost bite on sudden release on the 2019 test bike.","years":[2019],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Sprint enduro setup","fix":"A little less fork compression, a little more shock high-speed compression, rear ride height kept up, one tooth smaller rear sprocket for tight going","result":"Better balance in tight terrain","support":1}],"disagreements":[]},{"years":[2021,2022,2023],"generation":"2021-2023","summary":"Testers found this FX smooth and torquey down low, able to lug deep without much clutch and stall less than rivals, though the stock map 1 felt too aggressive and jerky off the bottom. The chassis felt more agile than the 2019-2020 but steered heavier in tight trees. Stock suspension suits slow technical terrain but is too soft for fast GP and desert racing.","points":[{"aspect":"mapping","verdict":"weakness","statement":"Stock map 1 feels too aggressive and jerky off the bottom; testers prefer softer maps for tight terrain.","years":[2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension is too soft for high-speed GP or desert racing and rides low; it works well in slow technical terrain.","years":[2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Smooth low-end torque that lugs deep with little clutch; stalls less than rivals.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"handling","verdict":"neutral","statement":"More agile and precise than 2019-2020 but with longer, heavier steering in tight trees.","years":[2021,2022,2023],"support":1,"strength":"single source"},{"aspect":"engine_mid","verdict":"neutral","statement":"About 53 hp on one magazine's dyno.","years":[2021,2022,2023],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Too soft for desert and GP","fix":"Stiffer fork and shock springs with minor valving changes, and 14/52 gearing","result":"Better bump absorption and bottoming resistance; chassis settles on acceleration and 2nd is usable in corners","support":1},{"problem":"Abrupt in tight terrain","fix":"Softer tester-made map","result":"Can lug with little clutch","support":2}],"disagreements":[]},{"years":[2024,2025,2026],"generation":"2024-2026 (based on the 2023 YZ450F)","summary":"Testers agree the FX is quick and strong through the mid and top, but they disagree on the low end: one magazine called it detuned and manageable, while another found the low-rpm response crisp enough to be unsettling and tuned the maps down. First gear is so low it is rarely used. The most common chassis complaint is a lack of stability at speed, with slight head shake in chop. Opinions on the KYB suspension range from plush and predictable to stiff and race-oriented.","points":[{"aspect":"stability","verdict":"weakness","statement":"Wants more stability at speed; slight head shake over high-speed chop.","years":[2024,2025,2026],"support":3,"strength":"strong consensus"},{"aspect":"gearing","verdict":"neutral","statement":"First gear is extremely low and rarely used; 2nd works in tight woods and 3rd is the key gear.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"handling","verdict":"neutral","statement":"Feels much lighter and more precise than earlier FX models, with a little front squirm under hard braking and less bump compliance.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"KYB spring fork rated the most predictable of the off-road 450s: plush and never blows through.","years":[2024],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"A 200 lb tester found the fork soft and sometimes harsh and slowed rebound; stock springs are slightly light for that weight.","years":[2024],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Seat shape, harsh grips and hard-to-grip sides; no stock handguards.","years":[2024,2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"neutral","statement":"Cable clutch survived a 10-hour race, but testers preferred the accessory hydraulic kit.","years":[2024],"support":1,"strength":"single source"},{"aspect":"mapping","verdict":"neutral","statement":"In tight or muddy terrain testers run the mellow map with the app power slider turned down and traction control on; fast riders keep the stock map.","years":[2024,2025,2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Head shake in high-speed chop","fix":"Two clicks more fork compression, 23.5 mm offset clamps, or a more stretched-out setup for fast races","result":"Head shake gone, more stability and plant; one setup turned worse when seated","support":3},{"problem":"Fast GP and desert","fix":"Fork 5 mm up (stock 8) with more compression, 100 mm sag, 14/52 or 14/53 gearing","result":"More stability at speed","support":1},{"problem":"Throttle jolts and stalling in tight terrain","fix":"Factory-accessory 50 g flywheel weight","result":"Smoother off idle and less stall risk; revs build slower, so 3rd is harder to pull for fast riders","support":1},{"problem":"Rocky GP flats","fix":"Foam mousse inserts","result":"No flats in rocky races","support":1}],"disagreements":[{"topic":"Low-end character","sides":["One race test called it detuned, quick-revving and manageable","Another found crisp, sometimes unsettling low-rpm response, and the 2026 stock map felt aggressive"]},{"topic":"Suspension feel","sides":["Rated plush and the most predictable of the off-road 450s","Found stiff and race-oriented on the 2026, or soft for a 200 lb rider"]}]}],"Yamaha|YZ250FX":[{"years":[2020,2021],"generation":"2020-2021","summary":"Testers liked the FX's strong bottom end and wide-ratio gearbox, which lets riders stay in one gear on most trails, with top-end pull close to the best 250Fs. The stock suspension suits East Coast roots and rocks but is too soft for fast GP, desert or motocross. Starting was a weak point, especially in gear or on hot restarts.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension is too soft and wallowy for fast GP, desert, motocross or aggressive riders.","years":[2020,2021],"support":3,"strength":"strong consensus"},{"aspect":"engine_low","verdict":"strength","statement":"Strong bottom end that lugs well; the wide-ratio box lets most trail be ridden in one gear.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"GNCC-style valving rolls over rocks and roots and suits East Coast woods.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Hard to start in gear and on hot restarts.","years":[2020,2021],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"strength","statement":"No mid-to-top drop-off, and top-end pull close to the hardest-pulling 250F, though it is not the quickest-revving.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"On MX or GP tracks riders hunt between 2nd-3rd and 3rd-4th.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"neutral","statement":"A long-term desert bike needed throttle cables and wheel bearings around 60 hours, clutch plates at 75 and a top end with timing chain around 80; its crank later failed after engine mods and long stretches on the rev limiter.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Too soft for fast racing","fix":"Stiffer springs, revalve and fork oil raised (295 cc to about 320-365 cc)","result":"More hold-up for braking and turns, smoother bottoming, less see-saw while keeping comfort","support":1},{"problem":"Gaps between gears on MX or GP","fix":"Add 1-2 teeth to the rear sprocket","result":"Less hunting between gears","support":1},{"problem":"Hard starting in gear","fix":"Start in neutral, or crack the throttle while pressing the starter","result":"Starts reliably","support":1}],"disagreements":[]},{"years":[2022,2023,2024],"generation":"2022-2024 engine update","summary":"Mainly one outlet's first impression. Testers found strong low-end torque that lugs and recovers from too tall a gear, a strong midrange and a top end competitive with the highest-revving 250Fs. The stock fork felt firm early and rode high while the shock felt soft, so the bike was unbalanced until the clickers were reset.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Exceptional low-end torque for a 250F that lugs and recovers from too tall a gear, with a strong mid and a competitive top end.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"balance","verdict":"weakness","statement":"Fork feels firm early and rides high while the shock is soft, leaving the bike unbalanced at stock settings.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"neutral","statement":"About 38 hp on one magazine's rear-wheel dyno, essentially the same as 2021.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Front-to-rear imbalance","fix":"Soften the fork clickers and add shock high-speed compression","result":"Balanced and raceable close to stock","support":1}],"disagreements":[]},{"years":[2025,2026],"generation":"2025-2026 (based on the 2024 YZ250F)","summary":"Testers found a longer, more linear powerband with a strong bottom-end hit, and suspension that stays plush over roots and rocks while resisting bottoming. Two separate tests reported the bike hard to start in gear even when warm.","points":[{"aspect":"other","verdict":"weakness","statement":"Hard to start in gear even when warm; riders restart in neutral.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"strength","statement":"Plush over rocks, roots and whoops yet resists bottoming at stock settings.","years":[2025,2026],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Longer, more linear powerband with a strong bottom-end hit.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"neutral","statement":"One tester sometimes wanted a lower 1st and taller 6th.","years":[2025,2026],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|YZ125":[{"years":[2020,2021],"generation":"2020-2021 (Mikuni carb engine)","summary":"Magazine tests found the older YZ125 pulled harder than the KTM 125 below about 8,000 rpm and was easy to keep on the pipe, but fell well behind it on top. Suspension is set up for light riders.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Pulls harder than the KTM 125 below about 8,000 rpm and is easy to keep on the pipe.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"weakness","statement":"Clearly slower than the KTM 125 above about 8,000 rpm, roughly 3-4 hp down at peak.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Set up for light riders; fast or heavy riders need stiffer springs.","years":[2020],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Stock gearing is slightly tall for a lugging style.","years":[2020],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Gearing slightly tall","fix":"13/49 sprocket","result":"More 2nd-gear grunt and earlier 3rd","support":1},{"problem":"Wants more power","fix":"Aftermarket pipe (about 2 hp); porting with raised compression and race gas for more","result":"Pipe choice moves power toward the top or toward the low-mid","support":2}],"disagreements":[]},{"years":[2022,2023,2024,2025,2026,2027],"generation":"2022-on new engine (Keihin carb, power jet)","summary":"The 2022 engine traded bottom end for more mid-to-top: testers found it weaker off the bottom and slower to come on the pipe, so riders slip the clutch out of turns, though pros liked it. On dynos it trails the European 125s. Many owners report rich jetting down low, with plug fouling and bogging, and lean it out. The suspension suits roughly 150-175 lb riders; heavier or faster riders find it soft.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Weaker off the bottom and slower to come on the pipe than the 2021; riders slip the clutch out of turns and beginners struggle.","years":[2022,2023,2024,2025,2026,2027],"support":3,"strength":"strong consensus"},{"aspect":"jetting","verdict":"weakness","statement":"Stock jetting runs rich low-to-mid: plug fouling on trails, burbling on coast-down and bogs off jump faces.","years":[2022,2023,2024,2025,2026,2027],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Makes the least peak power of the current 125s on magazine dynos.","years":[2022,2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Suspension suits roughly 150-175 lb riders; heavier or faster riders find it soft, even after the 2025 spring and valving change.","years":[2022,2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"engine_mid","verdict":"strength","statement":"Stronger from about 7,500 rpm to peak than the old engine; pros liked it.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"The 2022 springs and valving are too stiff for riders around 155 lb and for novice or vet riders.","years":[2022],"support":1,"strength":"single source"},{"aspect":"tires","verdict":"weakness","statement":"Stock front tire lost grip after 6-8 hours.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich low end, fouling and bog","fix":"Leaner pilot jet and a different needle (Y4 or CCL family), air screw about 1.25-1.75 turns, power jet adjusted","result":"Cleaner low end with no bog for most owners; no single fix works for everyone","support":3},{"problem":"Can't pull 3rd in deep soil or hills","fix":"13/50 rear sprocket","result":"3rd gear usable","support":1},{"problem":"More top end","fix":"Aftermarket pipe and silencer","result":"No change below about 9,500 rpm, then faster build and more over-rev (about 1.4 hp on one dyno)","support":2},{"problem":"Soft low end","fix":"Bolt-on package: pipe, ported cylinder and head, race piston, programmable ignition, reeds","result":"Soft low end gone and strong pull into the over-rev on race fuel","support":1}],"disagreements":[{"topic":"Midrange on track vs dyno","sides":["Dynos put it last among the current 125s","One magazine's riders still rated it strongest in the midrange, crediting its low flywheel effect"]}]}],"Yamaha|YZ250":[{"years":[2020,2021],"generation":"2020-2021 (pre-2022 bodywork)","summary":"The YZ250 engine has been largely unchanged since 2006. A magazine found it makes its best power higher in the revs and does not like being lugged, so riders need the clutch out of corners. The KTM 250 SX was stronger low-mid, but the Yamaha was easier to ride and kept pulling past its peak. Owners often find stock jetting rich down low.","points":[{"aspect":"engine_low","verdict":"weakness","statement":"Doesn't like being lugged and needs clutch out of corners; the KTM 250 SX is about 4 hp stronger around 7,000 rpm.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"engine_top","verdict":"strength","statement":"Keeps pulling past its peak and is easier to ride than the KTM.","years":[2020,2021],"support":1,"strength":"single source"},{"aspect":"jetting","verdict":"weakness","statement":"Stock pilot runs rich at the bottom near sea level.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Rich low end","fix":"Leaner pilot (about 45-48) and smaller power jet, needle clip adjusted","result":"Cleaner low end; one trail rider stopped fouling plugs","support":2},{"problem":"Off-idle dip","fix":"Re-time the power-valve governor by changing thrust washers so the valve opens earlier","result":"Fills the dip; needs a leaner power jet","support":1},{"problem":"More power","fix":"Aftermarket pipe","result":"About 2.5 hp more, mostly mid and up; too strong a hit for some vets on hard-pack","support":1}],"disagreements":[]},{"years":[2022,2023,2024,2025,2026,2027],"generation":"2022-on bodywork, airbox and suspension update","summary":"Testers describe a clean bottom and a hard-hitting midrange that needs a careful throttle into turns, pulling steadily to about 8,800 rpm. Lighter, slower and older riders found the stiffer 2022-on suspension harsh, while heavier riders found the stock springs light. The fork dives and pitches after break-in. Owners commonly lean out the jetting and tighten the head's squish.","points":[{"aspect":"suspension_front","verdict":"weakness","statement":"Stock springs are light for riders over about 155-170 lb.","years":[2022,2023,2024,2025,2026,2027],"support":3,"strength":"strong consensus"},{"aspect":"power_delivery","verdict":"neutral","statement":"Clean off idle with a hard-hitting midrange that needs careful throttle into turns; easy to keep in the meat, while the KTM is stronger low-mid but signs off sooner.","years":[2022,2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"The stiffer 2022-on valving feels harsh for vets, novices and light riders.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"After break-in the fork dives under hard braking and pitches the bike forward.","years":[2022,2023],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"The KYB setup has enough hold-up yet absorbs small bumps and feels balanced for an average rider.","years":[2024],"support":1,"strength":"single source"},{"aspect":"weight_feel","verdict":"strength","statement":"About 217 lb without fuel, roughly 10 lb lighter than a YZ250F.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"The rear-facing airbox scoops let water in when washing, and the 22 mm swingarm axle limits wheel swaps.","years":[2022,2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"jetting","verdict":"weakness","statement":"Owners often find stock jetting rich, even at the magazine's recommended settings.","years":[2025],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Springs too light for heavier riders","fix":"Stiffer springs (about 4.6 N/mm fork, 52 N/mm shock) or a respring with revalve","result":"One revalve fixed a fast-moving, knifing front and harsh mid-stroke while staying plush","support":2},{"problem":"Fork dives and pitches after break-in","fix":"Close up fork compression and rebound","result":"More hold-up","support":1},{"problem":"Rich jetting","fix":"Leaner pilot, smaller power jet and needle clip changes","result":"Cleaner running; adjust for season","support":2},{"problem":"Too much hit","fix":"Longer silencer, milder head insert, a few degrees of ignition retard, earlier power-valve spring or a flywheel weight","result":"More linear delivery; power-valve damper results were mixed","support":1},{"problem":"Large stock squish band","fix":"Mill the head to tighten squish to about 0.045 in on pump fuel","result":"Sharper running; head dowel bores may need deepening","support":1},{"problem":"Aftermarket pipe running rich","fix":"Raise needle one clip and drop the main one size","result":"Correct jetting with the pipe","support":1}],"disagreements":[{"topic":"How aggressive the power is","sides":["A magazine found it hits harder than the KTM in the midrange","Another tester found it smooth and manageable rather than abrupt"]}]}],"Yamaha|YZ125X":[{"years":[2020,2021,2022],"generation":"2020-2022 first generation (Mikuni)","summary":"Testers found the X much more tractable than the YZ125, smooth and torquey down low for a 125, which helps in tight woods. The top end is slower-revving and down on the European 125s. The soft cross-country suspension is plush on small hits but bottoms on big motocross impacts for heavier or faster riders. The small tank and lack of skid plate and handguards were the main practical complaints.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Smooth, controllable bottom end that lugs well for a 125; easier to recover from too tall a gear.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Soft cross-country settings bottom on big MX-style hits for heavier or faster riders; one tester called it badly undersprung at 190 lb.","years":[2020,2021,2022],"support":3,"strength":"strong consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Slower-revving and signs off early on top; clearly down on the Husqvarna TC125.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Small tank gives roughly 40 minutes of hard riding.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"No skid plate or handguards; motocross tires work poorly off-road and vice versa.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"brakes","verdict":"weakness","statement":"Front brake is only average.","years":[2021],"support":1,"strength":"single source"},{"aspect":"reliability","verdict":"strength","statement":"45 hours of riding with only routine maintenance; the cable clutch held up.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Front vague in chop and tight turns","fix":"Reduce race sag from about 110 mm to 107 mm","result":"More front traction in tight turns","support":1},{"problem":"Soft for MX use","fix":"Stiffer clickers and 10 cc more fork oil, or respring and revalve","result":"Better hold-up; heavier riders still need springs","support":2},{"problem":"Weak front brake","fix":"Oversize rotor and braided line","result":"Stronger front brake","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026,2027],"generation":"2023-on (Keihin engine)","summary":"Testers found the second-generation X surprisingly torquey for a 125. It has much more low end than the 2022-on YZ125 and less engine braking, but a weaker top end. The soft suspension soaks up rocks and roots, while heavier or faster riders may want it stiffer. There is still no electric start and the tank is small.","points":[{"aspect":"engine_low","verdict":"strength","statement":"Surprisingly torquey; it can lug a taller gear and has much more low end than the motocross YZ125.","years":[2023,2024,2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"engine_top","verdict":"weakness","statement":"Weaker top end; slower than the YZ125.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer KYB settings absorb repeated rock, root and braking-bump hits; heavier or faster riders may want it stiffer.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"No electric start and a small 1.8 gal tank that limits range.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Jetting for racing","fix":"Leaner pilot with a different needle and slide cutaway","result":"Cleaner running at race pace","support":1}],"disagreements":[]}],"Yamaha|YZ250X":[{"years":[2020,2021,2022],"generation":"2020-2022","summary":"Mainly one magazine's race test plus owner reports. The X is milder and more tractable than the YZ250, with a perky low-to-mid that suits rocky, tight terrain, but it does not make more power than the YZ250 anywhere. On a motocross track the tall 4th and 5th gears leave gaps, and the soft suspension bottoms on big jumps. Owners note it often finds neutral on 2-to-1 downshifts.","points":[{"aspect":"other","verdict":"weakness","statement":"Small tank and short reserve, no handguards or skid plate, kick start only.","years":[2020,2021,2022],"support":2,"strength":"consensus"},{"aspect":"power_delivery","verdict":"strength","statement":"Milder and more tractable than the YZ250 with a perky low-to-mid for rocky, tight terrain; it never out-powers the YZ250.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"weakness","statement":"Tall 4th and 5th leave big gaps on a motocross track.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"weakness","statement":"Soft suspension rides low and bottoms on big jumps for fast riders.","years":[2020,2021,2022],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Downshifting from 2nd to 1st on the move often finds neutral.","years":[2021],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Testers liked stiffer clutch springs better than the softer stock ones.","years":[2020,2021,2022],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Stalling and hard hits in tight terrain","fix":"Heavier flywheel, auto-clutch, revalve and respring, 13/51 gearing","result":"Easier trail manners; owners call the carb simple once set up","support":1}],"disagreements":[]},{"years":[2023,2024,2025,2026,2027],"generation":"2023-on","summary":"One outlet's test. The newer intake reduced the on/off feel at the bottom and mid while keeping the two-stroke rush on top. The soft suspension worked in the woods and on an MX track without bottoming.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Smooth, strong low end with less on/off feel, but still revs out like a 250 two-stroke.","years":[2023,2024,2025,2026,2027],"support":1,"strength":"single source"},{"aspect":"suspension_front","verdict":"strength","statement":"Softer than the YZ250 and absorbs roots and acceleration bumps without bottoming; go stiffer for fast western terrain.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[],"disagreements":[]}],"Yamaha|WR250F":[{"years":[2020,2021],"generation":"2020-2021","summary":"Little tester feedback exists for these years. The US bike ships restricted, and owners uncork it. Tall stock gearing made 2nd hard to hold in slow corners on one test bike.","points":[{"aspect":"engine_mid","verdict":"neutral","statement":"About 3 hp less than the YZ250F on the same magazine dyno in US form.","years":[2021],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted US engine","fix":"Remove throttle stop, muffler restrictor and intake restrictor; pair with the competition ECU and a little more fuel if the tailpipe comes out","result":"Engine runs closer to YZ-FX output","support":1},{"problem":"2nd gear runs out in slow corners","fix":"13/48 instead of 13/50 plus a slip-on and header","result":"Holds 2nd through slow corners; sharper response but less grip in slick going","support":1}],"disagreements":[]},{"years":[2022,2023,2024],"generation":"2022-2024 (YZ250F-derived frame)","summary":"One European test. Testers found the 2022 stronger across the range, especially mid to top where it revs freely. Stalling and slow hot restarts were still a trait. The small oil capacity calls for frequent oil changes.","points":[{"aspect":"engine_top","verdict":"strength","statement":"Stronger across the range, especially mid to top, revving freely so gears can be held longer.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Still stalls more readily than a two-stroke in technical going, and hot restarts are awkward; a softer map reduces stalling.","years":[2022,2023,2024],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"neutral","statement":"Small engine oil capacity, so testers advise frequent changes.","years":[2022,2023,2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted US engine","fix":"Remove throttle stop and restrictors and fit the competition ECU","result":"Stronger running; the ECU alone did not change off-idle response","support":1}],"disagreements":[]},{"years":[2025,2026,2027],"generation":"2025-on","summary":"Testers found the 2025 lively, with a bigger midrange kick and a smooth climb to a high rev limit. The softer handlebar map tames it. The KYB suspension splits opinion: firm and precise at speed, but stiff on slow technical trails for some, while a 90 kg rider rated it excellent without changes. It is still a little easy to stall, and hot restarts can be slow.","points":[{"aspect":"engine_mid","verdict":"strength","statement":"Lively, with a bigger midrange kick than before and smooth all the way to a high rev limit.","years":[2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork feels stiff on slow technical trails, though firm and precise at speed.","years":[2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"A little easy to stall, and hot restarts can take several seconds, worse after a stall on a hill.","years":[2025,2026,2027],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Fork transmits jolts through the arms over bigger chop for fast riders.","years":[2025],"support":1,"strength":"single source"},{"aspect":"gearing","verdict":"strength","statement":"Six-speed spread works from tight singletrack to fire roads.","years":[2025],"support":1,"strength":"single source"},{"aspect":"maintenance","verdict":"weakness","statement":"The linkage collects dirt, and the right-side axle marks are hidden, so align the wheel from the left.","years":[2026],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Chassis balance","fix":"Run less race sag than usual (about 95-100 mm)","result":"Better-balanced chassis","support":1},{"problem":"Slick conditions","fix":"Use the softer second map","result":"Flatter midrange with some traction-control effect","support":1}],"disagreements":[{"topic":"Stock suspension","sides":["Firm or stiff on slow technical trails","A 90 kg tester rated it a standout with no changes on grass track, enduro loops and trails"]}]}],"Yamaha|WR450F":[{"years":[2019,2020,2021,2022,2023],"generation":"2019-2023","summary":"In US form testers found the WR450F docile and torquey, great on slow, tight trails but short of punch in sand, hills and open terrain. Uncorking it and fitting the competition ECU transforms it to near-YZ450FX performance. The trail-valved suspension is soft early and progressive deeper and needs firming up for fast desert. Unrestricted Australian bikes felt the opposite, too aggressive on hard-pack.","points":[{"aspect":"power_delivery","verdict":"neutral","statement":"US-spec bike is docile and torquey with no real 450 hit; great on tight trails but struggles in sand, hills and open terrain.","years":[2019,2020,2021,2022,2023],"support":3,"strength":"strong consensus"},{"aspect":"suspension_front","verdict":"neutral","statement":"Same KYB hardware as the FX with softer trail valving: soft early, progressive deeper; firm it up for fast desert.","years":[2019,2020,2021,2022,2023],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"weakness","statement":"Stock bikes can stumble, cough or die when leaned over at low rpm.","years":[2021],"support":1,"strength":"single source"},{"aspect":"other","verdict":"weakness","statement":"Fuel range is far below claims when ridden hard; one test ran dry at 35 miles in sand.","years":[2023],"support":1,"strength":"single source"},{"aspect":"power_delivery","verdict":"weakness","statement":"Australian-spec 2019 felt too aggressive and tiring on hard-pack and rocks; the handlebar soft map did not calm it enough.","years":[2019],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Restricted, docile US engine","fix":"Remove throttle stop and intake/muffler restrictors and install the competition ECU, optionally with a slip-on","result":"Engine package close to the YZ450FX; one magazine estimated almost 20 hp more","support":2},{"problem":"Low-rpm stumble when leaned over","fix":"Remap through the communication unit","result":"Cured, even with the stock quiet pipe","support":1},{"problem":"Too aggressive (unrestricted bikes)","fix":"Softer app maps","result":"Far less aggressive in tight terrain","support":1}],"disagreements":[{"topic":"Stalling","sides":["One test found the stock bike stumbling and dying at low rpm when leaned over","Another 2021 test reported no stalling"]}]},{"years":[2024,2025,2026],"generation":"2024-2026 (YZ450F-derived chassis)","summary":"Testers find the newer WR450F punchy and willing to rev, with a very low first gear and enough torque in 2nd and 3rd to pull out of corners with little clutch. The app and mellow map can tame it a lot. Stock suspension felt firm at slow pace, so testers softened it with the fork knobs. The flameout trait of older WRs is mostly gone.","points":[{"aspect":"power_delivery","verdict":"strength","statement":"Punchy and willing to rev from mid to top with good low-speed traction; the app and mellow map tame it for slick going or beginners.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"suspension_front","verdict":"weakness","statement":"Stock suspension feels firm at slow pace; testers softened compression.","years":[2024,2025,2026],"support":2,"strength":"consensus"},{"aspect":"other","verdict":"neutral","statement":"Flameout is mostly gone, but bogging it in too high a gear can still make it sputter.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"ergonomics","verdict":"weakness","statement":"Tall seat.","years":[2025,2026],"support":1,"strength":"single source"},{"aspect":"clutch","verdict":"weakness","statement":"Clutch pull felt heavy at first; moving the perch outward helped.","years":[2024],"support":1,"strength":"single source"}],"common_fixes":[{"problem":"Slick conditions","fix":"Start on the mellow map and switch to full power as the ground dries","result":"Better traction","support":1}],"disagreements":[]}]};
